{"key": "cis.quality_detectors.struct_day_structure.day_output_gap", "label": "Quality check mode: missing day (broken day plan)", "guide": {"en": {"what": "The check that flags a source day missing from the text on catalogue tour rewrites (a code check against the source's day plan, no AI cost). It belongs to the error type \"Broken day plan\": extra, missing, duplicated or reordered days, a going-home day in the middle of the trip, or a day count that does not match the duration. This setting only marks whether the check is a main (owner) check of that error type. Today it changes nothing about a piece, its score, a hold, a report or an evaluation. Its only effect: when a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "raise": "enforce (the stricter choice): the check is marked as a main check of its error type, the one the team relies on for that type. Nothing about a piece, its score, a hold, a report or an evaluation changes today. Only do it once its findings have proved right.", "lower": "warn or shadow (the looser choices; today the two behave the same): the check is no longer a main check of its error type. Nothing about a piece, its score, a hold, a report or an evaluation changes. If a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "when": "Promote it to enforce when a shadow period shows its findings are right; demote it when reviewers keep overruling its findings. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces.", "example": "With the default shadow: this check is not a main check of its error type; what it finds is handled by the check itself, as before."}, "vi": {"what": "Bước kiểm phát hiện một ngày của nguồn không có trong bài trên bản viết lại tour của catalogue (bước code so với lịch trình ngày của nguồn, không tốn phí AI). Bước này thuộc loại lỗi \"Lịch trình ngày bị hỏng\": ngày thừa, thiếu, lặp hay sai thứ tự, ngày về nằm giữa chuyến, hoặc số ngày không khớp thời lượng tour. Thiết lập này chỉ đánh dấu bước kiểm có phải bước kiểm chính (owner) của loại lỗi đó không. Hiện nay nó không đổi gì ở bài viết, điểm, việc giữ bài, báo cáo hay đánh giá. Tác dụng duy nhất: khi một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra tự động của code cảnh báo loại lỗi đó không còn gì canh giữ.", "raise": "enforce (lựa chọn chặt hơn): bước kiểm được đánh dấu là bước kiểm chính của loại lỗi, bước mà nhóm dựa vào cho loại lỗi đó. Hiện nay bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Chỉ nên đổi khi kết quả của bước kiểm đã được chứng minh là đúng.", "lower": "warn hoặc shadow (các lựa chọn nới hơn; hiện nay hai chế độ này như nhau): bước kiểm không còn là bước kiểm chính của loại lỗi. Bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Nếu một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra chất lượng tự động của code cảnh báo rằng loại lỗi đó không còn gì canh giữ.", "when": "Nâng lên enforce khi giai đoạn shadow cho thấy kết quả đúng; hạ xuống khi người duyệt liên tục bác kết quả của nó. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu.", "example": "Với mặc định shadow: bước kiểm này không phải bước kiểm chính của loại lỗi; những gì nó phát hiện vẫn do chính bước kiểm xử lý như trước."}}},
{"key": "cis.quality_detectors.struct_day_structure.day_output_order", "label": "Quality check mode: days out of order (broken day plan)", "guide": {"en": {"what": "The check that flags days written out of order on catalogue tour rewrites (a code check against the source's day plan, no AI cost). It belongs to the error type \"Broken day plan\": extra, missing, duplicated or reordered days, a going-home day in the middle of the trip, or a day count that does not match the duration. This setting only marks whether the check is a main (owner) check of that error type. Today it changes nothing about a piece, its score, a hold, a report or an evaluation. Its only effect: when a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "raise": "enforce (the stricter choice): the check is marked as a main check of its error type, the one the team relies on for that type. Nothing about a piece, its score, a hold, a report or an evaluation changes today. Only do it once its findings have proved right.", "lower": "warn or shadow (the looser choices; today the two behave the same): the check is no longer a main check of its error type. Nothing about a piece, its score, a hold, a report or an evaluation changes. If a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "when": "Promote it to enforce when a shadow period shows its findings are right; demote it when reviewers keep overruling its findings. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces.", "example": "With the default shadow: this check is not a main check of its error type; what it finds is handled by the check itself, as before."}, "vi": {"what": "Bước kiểm phát hiện các ngày được viết sai thứ tự trên bản viết lại tour của catalogue (bước code so với lịch trình ngày của nguồn, không tốn phí AI). Bước này thuộc loại lỗi \"Lịch trình ngày bị hỏng\": ngày thừa, thiếu, lặp hay sai thứ tự, ngày về nằm giữa chuyến, hoặc số ngày không khớp thời lượng tour. Thiết lập này chỉ đánh dấu bước kiểm có phải bước kiểm chính (owner) của loại lỗi đó không. Hiện nay nó không đổi gì ở bài viết, điểm, việc giữ bài, báo cáo hay đánh giá. Tác dụng duy nhất: khi một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra tự động của code cảnh báo loại lỗi đó không còn gì canh giữ.", "raise": "enforce (lựa chọn chặt hơn): bước kiểm được đánh dấu là bước kiểm chính của loại lỗi, bước mà nhóm dựa vào cho loại lỗi đó. Hiện nay bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Chỉ nên đổi khi kết quả của bước kiểm đã được chứng minh là đúng.", "lower": "warn hoặc shadow (các lựa chọn nới hơn; hiện nay hai chế độ này như nhau): bước kiểm không còn là bước kiểm chính của loại lỗi. Bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Nếu một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra chất lượng tự động của code cảnh báo rằng loại lỗi đó không còn gì canh giữ.", "when": "Nâng lên enforce khi giai đoạn shadow cho thấy kết quả đúng; hạ xuống khi người duyệt liên tục bác kết quả của nó. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu.", "example": "Với mặc định shadow: bước kiểm này không phải bước kiểm chính của loại lỗi; những gì nó phát hiện vẫn do chính bước kiểm xử lý như trước."}}},
{"key": "cis.quality_detectors.struct_day_structure.day_place_mismatch", "label": "Quality check mode: place on the wrong day (broken day plan)", "guide": {"en": {"what": "The check that flags a day that names places the source puts on another day on catalogue tour rewrites (a fixed rule in code, no AI cost). It belongs to the error type \"Broken day plan\": extra, missing, duplicated or reordered days, a going-home day in the middle of the trip, or a day count that does not match the duration. This setting only marks whether the check is a main (owner) check of that error type. Today it changes nothing about a piece, its score, a hold, a report or an evaluation. Its only effect: when a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "raise": "enforce (the stricter choice): the check is marked as a main check of its error type, the one the team relies on for that type. Nothing about a piece, its score, a hold, a report or an evaluation changes today. Only do it once its findings have proved right.", "lower": "warn or shadow (the looser choices; today the two behave the same): the check is no longer a main check of its error type. Nothing about a piece, its score, a hold, a report or an evaluation changes. If a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "when": "Promote it to enforce when a shadow period shows its findings are right; demote it when reviewers keep overruling its findings. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces.", "example": "With the default shadow: this check is not a main check of its error type; what it finds is handled by the check itself, as before."}, "vi": {"what": "Bước kiểm phát hiện một ngày nêu địa điểm mà nguồn xếp vào ngày khác trên bản viết lại tour của catalogue (quy tắc cố định trong code, không tốn phí AI). Bước này thuộc loại lỗi \"Lịch trình ngày bị hỏng\": ngày thừa, thiếu, lặp hay sai thứ tự, ngày về nằm giữa chuyến, hoặc số ngày không khớp thời lượng tour. Thiết lập này chỉ đánh dấu bước kiểm có phải bước kiểm chính (owner) của loại lỗi đó không. Hiện nay nó không đổi gì ở bài viết, điểm, việc giữ bài, báo cáo hay đánh giá. Tác dụng duy nhất: khi một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra tự động của code cảnh báo loại lỗi đó không còn gì canh giữ.", "raise": "enforce (lựa chọn chặt hơn): bước kiểm được đánh dấu là bước kiểm chính của loại lỗi, bước mà nhóm dựa vào cho loại lỗi đó. Hiện nay bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Chỉ nên đổi khi kết quả của bước kiểm đã được chứng minh là đúng.", "lower": "warn hoặc shadow (các lựa chọn nới hơn; hiện nay hai chế độ này như nhau): bước kiểm không còn là bước kiểm chính của loại lỗi. Bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Nếu một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra chất lượng tự động của code cảnh báo rằng loại lỗi đó không còn gì canh giữ.", "when": "Nâng lên enforce khi giai đoạn shadow cho thấy kết quả đúng; hạ xuống khi người duyệt liên tục bác kết quả của nó. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu.", "example": "Với mặc định shadow: bước kiểm này không phải bước kiểm chính của loại lỗi; những gì nó phát hiện vẫn do chính bước kiểm xử lý như trước."}}},
{"key": "cis.quality_detectors.struct_day_structure.day_subday_split", "label": "Quality check mode: one day split in several (broken day plan)", "guide": {"en": {"what": "The check that flags one source day split into several written days on catalogue tour rewrites (a code check against the source's day plan, no AI cost). It belongs to the error type \"Broken day plan\": extra, missing, duplicated or reordered days, a going-home day in the middle of the trip, or a day count that does not match the duration. This setting only marks whether the check is a main (owner) check of that error type. Today it changes nothing about a piece, its score, a hold, a report or an evaluation. Its only effect: when a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "raise": "enforce (the stricter choice): the check is marked as a main check of its error type, the one the team relies on for that type. Nothing about a piece, its score, a hold, a report or an evaluation changes today. Only do it once its findings have proved right.", "lower": "warn or shadow (the looser choices; today the two behave the same): the check is no longer a main check of its error type. Nothing about a piece, its score, a hold, a report or an evaluation changes. If a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "when": "Promote it to enforce when a shadow period shows its findings are right; demote it when reviewers keep overruling its findings. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces.", "example": "With the default shadow: this check is not a main check of its error type; what it finds is handled by the check itself, as before."}, "vi": {"what": "Bước kiểm phát hiện một ngày của nguồn bị tách thành nhiều ngày trong bài trên bản viết lại tour của catalogue (bước code so với lịch trình ngày của nguồn, không tốn phí AI). Bước này thuộc loại lỗi \"Lịch trình ngày bị hỏng\": ngày thừa, thiếu, lặp hay sai thứ tự, ngày về nằm giữa chuyến, hoặc số ngày không khớp thời lượng tour. Thiết lập này chỉ đánh dấu bước kiểm có phải bước kiểm chính (owner) của loại lỗi đó không. Hiện nay nó không đổi gì ở bài viết, điểm, việc giữ bài, báo cáo hay đánh giá. Tác dụng duy nhất: khi một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra tự động của code cảnh báo loại lỗi đó không còn gì canh giữ.", "raise": "enforce (lựa chọn chặt hơn): bước kiểm được đánh dấu là bước kiểm chính của loại lỗi, bước mà nhóm dựa vào cho loại lỗi đó. Hiện nay bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Chỉ nên đổi khi kết quả của bước kiểm đã được chứng minh là đúng.", "lower": "warn hoặc shadow (các lựa chọn nới hơn; hiện nay hai chế độ này như nhau): bước kiểm không còn là bước kiểm chính của loại lỗi. Bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Nếu một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra chất lượng tự động của code cảnh báo rằng loại lỗi đó không còn gì canh giữ.", "when": "Nâng lên enforce khi giai đoạn shadow cho thấy kết quả đúng; hạ xuống khi người duyệt liên tục bác kết quả của nó. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu.", "example": "Với mặc định shadow: bước kiểm này không phải bước kiểm chính của loại lỗi; những gì nó phát hiện vẫn do chính bước kiểm xử lý như trước."}}},
{"key": "cis.quality_detectors.struct_day_structure.itinerary_day_count_mismatch", "label": "Quality check mode: day count differs from the source (broken day plan)", "guide": {"en": {"what": "The check that flags an itinerary with a different number of days than the source on catalogue tour rewrites (a code check against the source's day plan, no AI cost). It belongs to the error type \"Broken day plan\": extra, missing, duplicated or reordered days, a going-home day in the middle of the trip, or a day count that does not match the duration. This setting only marks whether the check is a main (owner) check of that error type. Today it changes nothing about a piece, its score, a hold, a report or an evaluation. Its only effect: when a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "raise": "enforce (the stricter choice): the check is marked as a main check of its error type, the one the team relies on for that type. Nothing about a piece, its score, a hold, a report or an evaluation changes today. Only do it once its findings have proved right.", "lower": "warn or shadow (the looser choices; today the two behave the same): the check is no longer a main check of its error type. Nothing about a piece, its score, a hold, a report or an evaluation changes. If a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "when": "Promote it to enforce when a shadow period shows its findings are right; demote it when reviewers keep overruling its findings. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces.", "example": "With the default enforce: this check is marked as a main check of its error type."}, "vi": {"what": "Bước kiểm phát hiện lịch trình có số ngày khác với nguồn trên bản viết lại tour của catalogue (bước code so với lịch trình ngày của nguồn, không tốn phí AI). Bước này thuộc loại lỗi \"Lịch trình ngày bị hỏng\": ngày thừa, thiếu, lặp hay sai thứ tự, ngày về nằm giữa chuyến, hoặc số ngày không khớp thời lượng tour. Thiết lập này chỉ đánh dấu bước kiểm có phải bước kiểm chính (owner) của loại lỗi đó không. Hiện nay nó không đổi gì ở bài viết, điểm, việc giữ bài, báo cáo hay đánh giá. Tác dụng duy nhất: khi một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra tự động của code cảnh báo loại lỗi đó không còn gì canh giữ.", "raise": "enforce (lựa chọn chặt hơn): bước kiểm được đánh dấu là bước kiểm chính của loại lỗi, bước mà nhóm dựa vào cho loại lỗi đó. Hiện nay bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Chỉ nên đổi khi kết quả của bước kiểm đã được chứng minh là đúng.", "lower": "warn hoặc shadow (các lựa chọn nới hơn; hiện nay hai chế độ này như nhau): bước kiểm không còn là bước kiểm chính của loại lỗi. Bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Nếu một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra chất lượng tự động của code cảnh báo rằng loại lỗi đó không còn gì canh giữ.", "when": "Nâng lên enforce khi giai đoạn shadow cho thấy kết quả đúng; hạ xuống khi người duyệt liên tục bác kết quả của nó. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu.", "example": "Với mặc định enforce: bước kiểm này được đánh dấu là bước kiểm chính của loại lỗi."}}},
{"key": "cis.quality_detectors.struct_day_structure.itinerary_still_compressed", "label": "Quality check mode: days still squeezed together (broken day plan)", "guide": {"en": {"what": "The check that flags an itinerary that still squeezes several source days into one on catalogue tour rewrites (a code check against the source's day plan, no AI cost). It belongs to the error type \"Broken day plan\": extra, missing, duplicated or reordered days, a going-home day in the middle of the trip, or a day count that does not match the duration. This setting only marks whether the check is a main (owner) check of that error type. Today it changes nothing about a piece, its score, a hold, a report or an evaluation. Its only effect: when a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "raise": "enforce (the stricter choice): the check is marked as a main check of its error type, the one the team relies on for that type. Nothing about a piece, its score, a hold, a report or an evaluation changes today. Only do it once its findings have proved right.", "lower": "warn or shadow (the looser choices; today the two behave the same): the check is no longer a main check of its error type. Nothing about a piece, its score, a hold, a report or an evaluation changes. If a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "when": "Promote it to enforce when a shadow period shows its findings are right; demote it when reviewers keep overruling its findings. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces.", "example": "With the default warn: this check is not a main check of its error type; what it finds is handled by the check itself, as before."}, "vi": {"what": "Bước kiểm phát hiện lịch trình vẫn gộp nhiều ngày của nguồn vào một ngày trên bản viết lại tour của catalogue (bước code so với lịch trình ngày của nguồn, không tốn phí AI). Bước này thuộc loại lỗi \"Lịch trình ngày bị hỏng\": ngày thừa, thiếu, lặp hay sai thứ tự, ngày về nằm giữa chuyến, hoặc số ngày không khớp thời lượng tour. Thiết lập này chỉ đánh dấu bước kiểm có phải bước kiểm chính (owner) của loại lỗi đó không. Hiện nay nó không đổi gì ở bài viết, điểm, việc giữ bài, báo cáo hay đánh giá. Tác dụng duy nhất: khi một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra tự động của code cảnh báo loại lỗi đó không còn gì canh giữ.", "raise": "enforce (lựa chọn chặt hơn): bước kiểm được đánh dấu là bước kiểm chính của loại lỗi, bước mà nhóm dựa vào cho loại lỗi đó. Hiện nay bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Chỉ nên đổi khi kết quả của bước kiểm đã được chứng minh là đúng.", "lower": "warn hoặc shadow (các lựa chọn nới hơn; hiện nay hai chế độ này như nhau): bước kiểm không còn là bước kiểm chính của loại lỗi. Bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Nếu một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra chất lượng tự động của code cảnh báo rằng loại lỗi đó không còn gì canh giữ.", "when": "Nâng lên enforce khi giai đoạn shadow cho thấy kết quả đúng; hạ xuống khi người duyệt liên tục bác kết quả của nó. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu.", "example": "Với mặc định warn: bước kiểm này không phải bước kiểm chính của loại lỗi; những gì nó phát hiện vẫn do chính bước kiểm xử lý như trước."}}},
{"key": "cis.quality_detectors.struct_day_structure.itinerary_structure_weak", "label": "Quality check mode: weak day structure (broken day plan)", "guide": {"en": {"what": "The check that flags days without a clear plan of their own on catalogue tour rewrites (a fixed rule in code, no AI cost). It belongs to the error type \"Broken day plan\": extra, missing, duplicated or reordered days, a going-home day in the middle of the trip, or a day count that does not match the duration. This setting only marks whether the check is a main (owner) check of that error type. Today it changes nothing about a piece, its score, a hold, a report or an evaluation. Its only effect: when a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "raise": "enforce (the stricter choice): the check is marked as a main check of its error type, the one the team relies on for that type. Nothing about a piece, its score, a hold, a report or an evaluation changes today. Only do it once its findings have proved right.", "lower": "warn or shadow (the looser choices; today the two behave the same): the check is no longer a main check of its error type. Nothing about a piece, its score, a hold, a report or an evaluation changes. If a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "when": "Promote it to enforce when a shadow period shows its findings are right; demote it when reviewers keep overruling its findings. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces.", "example": "With the default warn: this check is not a main check of its error type; what it finds is handled by the check itself, as before."}, "vi": {"what": "Bước kiểm phát hiện các ngày không có kế hoạch rõ ràng trên bản viết lại tour của catalogue (quy tắc cố định trong code, không tốn phí AI). Bước này thuộc loại lỗi \"Lịch trình ngày bị hỏng\": ngày thừa, thiếu, lặp hay sai thứ tự, ngày về nằm giữa chuyến, hoặc số ngày không khớp thời lượng tour. Thiết lập này chỉ đánh dấu bước kiểm có phải bước kiểm chính (owner) của loại lỗi đó không. Hiện nay nó không đổi gì ở bài viết, điểm, việc giữ bài, báo cáo hay đánh giá. Tác dụng duy nhất: khi một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra tự động của code cảnh báo loại lỗi đó không còn gì canh giữ.", "raise": "enforce (lựa chọn chặt hơn): bước kiểm được đánh dấu là bước kiểm chính của loại lỗi, bước mà nhóm dựa vào cho loại lỗi đó. Hiện nay bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Chỉ nên đổi khi kết quả của bước kiểm đã được chứng minh là đúng.", "lower": "warn hoặc shadow (các lựa chọn nới hơn; hiện nay hai chế độ này như nhau): bước kiểm không còn là bước kiểm chính của loại lỗi. Bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Nếu một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra chất lượng tự động của code cảnh báo rằng loại lỗi đó không còn gì canh giữ.", "when": "Nâng lên enforce khi giai đoạn shadow cho thấy kết quả đúng; hạ xuống khi người duyệt liên tục bác kết quả của nó. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu.", "example": "Với mặc định warn: bước kiểm này không phải bước kiểm chính của loại lỗi; những gì nó phát hiện vẫn do chính bước kiểm xử lý như trước."}}},
{"key": "cis.quality_detectors.struct_day_structure.repair_contract", "label": "Quality check mode: repair limits (broken day plan)", "guide": {"en": {"what": "The check that flags an automatic repair that broke its limits (added a new fact, cut text, dropped a day or left the scope) on catalogue tour rewrites (a fixed rule in code, no AI cost). It belongs to the error type \"Broken day plan\": extra, missing, duplicated or reordered days, a going-home day in the middle of the trip, or a day count that does not match the duration. This setting only marks whether the check is a main (owner) check of that error type. Today it changes nothing about a piece, its score, a hold, a report or an evaluation. Its only effect: when a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "raise": "enforce (the stricter choice): the check is marked as a main check of its error type, the one the team relies on for that type. Nothing about a piece, its score, a hold, a report or an evaluation changes today. Only do it once its findings have proved right.", "lower": "warn or shadow (the looser choices; today the two behave the same): the check is no longer a main check of its error type. Nothing about a piece, its score, a hold, a report or an evaluation changes. If a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "when": "Promote it to enforce when a shadow period shows its findings are right; demote it when reviewers keep overruling its findings. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces.", "example": "With the default shadow: this check is not a main check of its error type; what it finds is handled by the check itself, as before."}, "vi": {"what": "Bước kiểm phát hiện một lần sửa tự động vượt giới hạn (thêm dữ kiện mới, cắt chữ, bỏ ngày hay ra ngoài phạm vi) trên bản viết lại tour của catalogue (quy tắc cố định trong code, không tốn phí AI). Bước này thuộc loại lỗi \"Lịch trình ngày bị hỏng\": ngày thừa, thiếu, lặp hay sai thứ tự, ngày về nằm giữa chuyến, hoặc số ngày không khớp thời lượng tour. Thiết lập này chỉ đánh dấu bước kiểm có phải bước kiểm chính (owner) của loại lỗi đó không. Hiện nay nó không đổi gì ở bài viết, điểm, việc giữ bài, báo cáo hay đánh giá. Tác dụng duy nhất: khi một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra tự động của code cảnh báo loại lỗi đó không còn gì canh giữ.", "raise": "enforce (lựa chọn chặt hơn): bước kiểm được đánh dấu là bước kiểm chính của loại lỗi, bước mà nhóm dựa vào cho loại lỗi đó. Hiện nay bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Chỉ nên đổi khi kết quả của bước kiểm đã được chứng minh là đúng.", "lower": "warn hoặc shadow (các lựa chọn nới hơn; hiện nay hai chế độ này như nhau): bước kiểm không còn là bước kiểm chính của loại lỗi. Bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Nếu một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra chất lượng tự động của code cảnh báo rằng loại lỗi đó không còn gì canh giữ.", "when": "Nâng lên enforce khi giai đoạn shadow cho thấy kết quả đúng; hạ xuống khi người duyệt liên tục bác kết quả của nó. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu.", "example": "Với mặc định shadow: bước kiểm này không phải bước kiểm chính của loại lỗi; những gì nó phát hiện vẫn do chính bước kiểm xử lý như trước."}}},
{"key": "cis.quality_detectors.struct_leaked_instruction.f13_hygiene", "label": "Quality check mode: text hygiene (leaked instructions)", "guide": {"en": {"what": "The check that flags leaks, social proof, repeats and hashtag slips on blog articles and social posts (a fixed rule in code, no AI cost). It belongs to the error type \"Leaked instructions\": wording of the writing instructions or the brief that leaked into the text readers see. This setting only marks whether the check is a main (owner) check of that error type. Today it changes nothing about a piece, its score, a hold, a report or an evaluation. Its only effect: when a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "raise": "enforce (the stricter choice): the check is marked as a main check of its error type, the one the team relies on for that type. Nothing about a piece, its score, a hold, a report or an evaluation changes today. Only do it once its findings have proved right.", "lower": "warn or shadow (the looser choices; today the two behave the same): the check is no longer a main check of its error type. Nothing about a piece, its score, a hold, a report or an evaluation changes. If a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "when": "Promote it to enforce when a shadow period shows its findings are right; demote it when reviewers keep overruling its findings. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces.", "example": "With the default warn: this check is not a main check of its error type; what it finds is handled by the check itself, as before."}, "vi": {"what": "Bước kiểm phát hiện lộ chữ, lời chứng thực, lặp và lỗi hashtag trên bài blog và bài mạng xã hội (quy tắc cố định trong code, không tốn phí AI). Bước này thuộc loại lỗi \"Lộ hướng dẫn viết\": câu chữ của hướng dẫn viết hay brief lọt vào phần người đọc nhìn thấy. Thiết lập này chỉ đánh dấu bước kiểm có phải bước kiểm chính (owner) của loại lỗi đó không. Hiện nay nó không đổi gì ở bài viết, điểm, việc giữ bài, báo cáo hay đánh giá. Tác dụng duy nhất: khi một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra tự động của code cảnh báo loại lỗi đó không còn gì canh giữ.", "raise": "enforce (lựa chọn chặt hơn): bước kiểm được đánh dấu là bước kiểm chính của loại lỗi, bước mà nhóm dựa vào cho loại lỗi đó. Hiện nay bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Chỉ nên đổi khi kết quả của bước kiểm đã được chứng minh là đúng.", "lower": "warn hoặc shadow (các lựa chọn nới hơn; hiện nay hai chế độ này như nhau): bước kiểm không còn là bước kiểm chính của loại lỗi. Bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Nếu một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra chất lượng tự động của code cảnh báo rằng loại lỗi đó không còn gì canh giữ.", "when": "Nâng lên enforce khi giai đoạn shadow cho thấy kết quả đúng; hạ xuống khi người duyệt liên tục bác kết quả của nó. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu.", "example": "Với mặc định warn: bước kiểm này không phải bước kiểm chính của loại lỗi; những gì nó phát hiện vẫn do chính bước kiểm xử lý như trước."}}},
{"key": "cis.quality_detectors.struct_leaked_instruction.f13_leak", "label": "Quality check mode: leak or broken opener (leaked instructions)", "guide": {"en": {"what": "The check that flags writing instructions or the audience leaking into the text, or an opening line that refers to nothing on blog articles and social posts (a fixed rule in code, no AI cost). It belongs to the error type \"Leaked instructions\": wording of the writing instructions or the brief that leaked into the text readers see. This setting only marks whether the check is a main (owner) check of that error type. Today it changes nothing about a piece, its score, a hold, a report or an evaluation. Its only effect: when a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "raise": "enforce (the stricter choice): the check is marked as a main check of its error type, the one the team relies on for that type. Nothing about a piece, its score, a hold, a report or an evaluation changes today. Only do it once its findings have proved right.", "lower": "warn or shadow (the looser choices; today the two behave the same): the check is no longer a main check of its error type. Nothing about a piece, its score, a hold, a report or an evaluation changes. If a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "when": "Promote it to enforce when a shadow period shows its findings are right; demote it when reviewers keep overruling its findings. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces.", "example": "With the default enforce: this check is marked as a main check of its error type."}, "vi": {"what": "Bước kiểm phát hiện hướng dẫn viết hay đối tượng khách lọt vào bài, hoặc câu mở đầu không ăn nhập trên bài blog và bài mạng xã hội (quy tắc cố định trong code, không tốn phí AI). Bước này thuộc loại lỗi \"Lộ hướng dẫn viết\": câu chữ của hướng dẫn viết hay brief lọt vào phần người đọc nhìn thấy. Thiết lập này chỉ đánh dấu bước kiểm có phải bước kiểm chính (owner) của loại lỗi đó không. Hiện nay nó không đổi gì ở bài viết, điểm, việc giữ bài, báo cáo hay đánh giá. Tác dụng duy nhất: khi một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra tự động của code cảnh báo loại lỗi đó không còn gì canh giữ.", "raise": "enforce (lựa chọn chặt hơn): bước kiểm được đánh dấu là bước kiểm chính của loại lỗi, bước mà nhóm dựa vào cho loại lỗi đó. Hiện nay bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Chỉ nên đổi khi kết quả của bước kiểm đã được chứng minh là đúng.", "lower": "warn hoặc shadow (các lựa chọn nới hơn; hiện nay hai chế độ này như nhau): bước kiểm không còn là bước kiểm chính của loại lỗi. Bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Nếu một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra chất lượng tự động của code cảnh báo rằng loại lỗi đó không còn gì canh giữ.", "when": "Nâng lên enforce khi giai đoạn shadow cho thấy kết quả đúng; hạ xuống khi người duyệt liên tục bác kết quả của nó. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu.", "example": "Với mặc định enforce: bước kiểm này được đánh dấu là bước kiểm chính của loại lỗi."}}},
{"key": "cis.quality_detectors.struct_truncated.f0_complete", "label": "Quality check mode: piece cut off before its end (cut-off text)", "guide": {"en": {"what": "The check that flags a piece cut off before its end on blog articles and social posts (a fixed rule in code, no AI cost). It belongs to the error type \"Cut-off text\": a field cut off mid-sentence, or a required field left empty. This setting only marks whether the check is a main (owner) check of that error type. Today it changes nothing about a piece, its score, a hold, a report or an evaluation. Its only effect: when a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "raise": "enforce (the stricter choice): the check is marked as a main check of its error type, the one the team relies on for that type. Nothing about a piece, its score, a hold, a report or an evaluation changes today. Only do it once its findings have proved right.", "lower": "warn or shadow (the looser choices; today the two behave the same): the check is no longer a main check of its error type. Nothing about a piece, its score, a hold, a report or an evaluation changes. If a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "when": "Promote it to enforce when a shadow period shows its findings are right; demote it when reviewers keep overruling its findings. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces.", "example": "With the default enforce: this check is marked as a main check of its error type."}, "vi": {"what": "Bước kiểm phát hiện bài bị cắt trước khi kết thúc trên bài blog và bài mạng xã hội (quy tắc cố định trong code, không tốn phí AI). Bước này thuộc loại lỗi \"Văn bản bị cắt\": một trường bị cắt giữa câu, hoặc một trường bắt buộc bị bỏ trống. Thiết lập này chỉ đánh dấu bước kiểm có phải bước kiểm chính (owner) của loại lỗi đó không. Hiện nay nó không đổi gì ở bài viết, điểm, việc giữ bài, báo cáo hay đánh giá. Tác dụng duy nhất: khi một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra tự động của code cảnh báo loại lỗi đó không còn gì canh giữ.", "raise": "enforce (lựa chọn chặt hơn): bước kiểm được đánh dấu là bước kiểm chính của loại lỗi, bước mà nhóm dựa vào cho loại lỗi đó. Hiện nay bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Chỉ nên đổi khi kết quả của bước kiểm đã được chứng minh là đúng.", "lower": "warn hoặc shadow (các lựa chọn nới hơn; hiện nay hai chế độ này như nhau): bước kiểm không còn là bước kiểm chính của loại lỗi. Bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Nếu một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra chất lượng tự động của code cảnh báo rằng loại lỗi đó không còn gì canh giữ.", "when": "Nâng lên enforce khi giai đoạn shadow cho thấy kết quả đúng; hạ xuống khi người duyệt liên tục bác kết quả của nó. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu.", "example": "Với mặc định enforce: bước kiểm này được đánh dấu là bước kiểm chính của loại lỗi."}}},
{"key": "cis.quality_detectors.struct_truncated.meta_cut", "label": "Quality check mode: cut search description (cut-off text)", "guide": {"en": {"what": "The check that flags a search description cut at its length limit on catalogue tour rewrites (a fixed rule in code, no AI cost). It belongs to the error type \"Cut-off text\": a field cut off mid-sentence, or a required field left empty. This setting only marks whether the check is a main (owner) check of that error type. Today it changes nothing about a piece, its score, a hold, a report or an evaluation. Its only effect: when a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "raise": "enforce (the stricter choice): the check is marked as a main check of its error type, the one the team relies on for that type. Nothing about a piece, its score, a hold, a report or an evaluation changes today. Only do it once its findings have proved right.", "lower": "warn or shadow (the looser choices; today the two behave the same): the check is no longer a main check of its error type. Nothing about a piece, its score, a hold, a report or an evaluation changes. If a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "when": "Promote it to enforce when a shadow period shows its findings are right; demote it when reviewers keep overruling its findings. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces.", "example": "With the default shadow: this check is not a main check of its error type; what it finds is handled by the check itself, as before."}, "vi": {"what": "Bước kiểm phát hiện mô tả tìm kiếm bị cắt ở giới hạn độ dài trên bản viết lại tour của catalogue (quy tắc cố định trong code, không tốn phí AI). Bước này thuộc loại lỗi \"Văn bản bị cắt\": một trường bị cắt giữa câu, hoặc một trường bắt buộc bị bỏ trống. Thiết lập này chỉ đánh dấu bước kiểm có phải bước kiểm chính (owner) của loại lỗi đó không. Hiện nay nó không đổi gì ở bài viết, điểm, việc giữ bài, báo cáo hay đánh giá. Tác dụng duy nhất: khi một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra tự động của code cảnh báo loại lỗi đó không còn gì canh giữ.", "raise": "enforce (lựa chọn chặt hơn): bước kiểm được đánh dấu là bước kiểm chính của loại lỗi, bước mà nhóm dựa vào cho loại lỗi đó. Hiện nay bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Chỉ nên đổi khi kết quả của bước kiểm đã được chứng minh là đúng.", "lower": "warn hoặc shadow (các lựa chọn nới hơn; hiện nay hai chế độ này như nhau): bước kiểm không còn là bước kiểm chính của loại lỗi. Bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Nếu một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra chất lượng tự động của code cảnh báo rằng loại lỗi đó không còn gì canh giữ.", "when": "Nâng lên enforce khi giai đoạn shadow cho thấy kết quả đúng; hạ xuống khi người duyệt liên tục bác kết quả của nó. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu.", "example": "Với mặc định shadow: bước kiểm này không phải bước kiểm chính của loại lỗi; những gì nó phát hiện vẫn do chính bước kiểm xử lý như trước."}}},
{"key": "cis.quality_detectors.struct_truncated.meta_cut_signature", "label": "Quality check mode: cut search description (pattern) (cut-off text)", "guide": {"en": {"what": "The check that flags a search description that shows the typical pattern of a cut (a clause closed by a full stop) on catalogue tour rewrites (a fixed rule in code, no AI cost). It belongs to the error type \"Cut-off text\": a field cut off mid-sentence, or a required field left empty. This setting only marks whether the check is a main (owner) check of that error type. Today it changes nothing about a piece, its score, a hold, a report or an evaluation. Its only effect: when a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "raise": "enforce (the stricter choice): the check is marked as a main check of its error type, the one the team relies on for that type. Nothing about a piece, its score, a hold, a report or an evaluation changes today. Only do it once its findings have proved right.", "lower": "warn or shadow (the looser choices; today the two behave the same): the check is no longer a main check of its error type. Nothing about a piece, its score, a hold, a report or an evaluation changes. If a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "when": "Promote it to enforce when a shadow period shows its findings are right; demote it when reviewers keep overruling its findings. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces.", "example": "With the default shadow: this check is not a main check of its error type; what it finds is handled by the check itself, as before."}, "vi": {"what": "Bước kiểm phát hiện mô tả tìm kiếm có dấu hiệu bị cắt điển hình (một mệnh đề dở dang kết bằng dấu chấm) trên bản viết lại tour của catalogue (quy tắc cố định trong code, không tốn phí AI). Bước này thuộc loại lỗi \"Văn bản bị cắt\": một trường bị cắt giữa câu, hoặc một trường bắt buộc bị bỏ trống. Thiết lập này chỉ đánh dấu bước kiểm có phải bước kiểm chính (owner) của loại lỗi đó không. Hiện nay nó không đổi gì ở bài viết, điểm, việc giữ bài, báo cáo hay đánh giá. Tác dụng duy nhất: khi một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra tự động của code cảnh báo loại lỗi đó không còn gì canh giữ.", "raise": "enforce (lựa chọn chặt hơn): bước kiểm được đánh dấu là bước kiểm chính của loại lỗi, bước mà nhóm dựa vào cho loại lỗi đó. Hiện nay bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Chỉ nên đổi khi kết quả của bước kiểm đã được chứng minh là đúng.", "lower": "warn hoặc shadow (các lựa chọn nới hơn; hiện nay hai chế độ này như nhau): bước kiểm không còn là bước kiểm chính của loại lỗi. Bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Nếu một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra chất lượng tự động của code cảnh báo rằng loại lỗi đó không còn gì canh giữ.", "when": "Nâng lên enforce khi giai đoạn shadow cho thấy kết quả đúng; hạ xuống khi người duyệt liên tục bác kết quả của nó. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu.", "example": "Với mặc định shadow: bước kiểm này không phải bước kiểm chính của loại lỗi; những gì nó phát hiện vẫn do chính bước kiểm xử lý như trước."}}},
{"key": "cis.quality_detectors.struct_truncated.meta_incomplete_sentence", "label": "Quality check mode: search description ends mid-sentence (cut-off text)", "guide": {"en": {"what": "The check that flags a search description that ends with an unfinished sentence on catalogue tour rewrites and agency tour rewrites (a fixed rule in code, no AI cost). It belongs to the error type \"Cut-off text\": a field cut off mid-sentence, or a required field left empty. This setting only marks whether the check is a main (owner) check of that error type. Today it changes nothing about a piece, its score, a hold, a report or an evaluation. Its only effect: when a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "raise": "enforce (the stricter choice): the check is marked as a main check of its error type, the one the team relies on for that type. Nothing about a piece, its score, a hold, a report or an evaluation changes today. Only do it once its findings have proved right.", "lower": "warn or shadow (the looser choices; today the two behave the same): the check is no longer a main check of its error type. Nothing about a piece, its score, a hold, a report or an evaluation changes. If a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "when": "Promote it to enforce when a shadow period shows its findings are right; demote it when reviewers keep overruling its findings. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces.", "example": "With the default enforce: this check is marked as a main check of its error type."}, "vi": {"what": "Bước kiểm phát hiện mô tả tìm kiếm kết thúc bằng một câu chưa trọn trên bản viết lại tour của catalogue và bản viết lại tour cho đại lý (quy tắc cố định trong code, không tốn phí AI). Bước này thuộc loại lỗi \"Văn bản bị cắt\": một trường bị cắt giữa câu, hoặc một trường bắt buộc bị bỏ trống. Thiết lập này chỉ đánh dấu bước kiểm có phải bước kiểm chính (owner) của loại lỗi đó không. Hiện nay nó không đổi gì ở bài viết, điểm, việc giữ bài, báo cáo hay đánh giá. Tác dụng duy nhất: khi một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra tự động của code cảnh báo loại lỗi đó không còn gì canh giữ.", "raise": "enforce (lựa chọn chặt hơn): bước kiểm được đánh dấu là bước kiểm chính của loại lỗi, bước mà nhóm dựa vào cho loại lỗi đó. Hiện nay bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Chỉ nên đổi khi kết quả của bước kiểm đã được chứng minh là đúng.", "lower": "warn hoặc shadow (các lựa chọn nới hơn; hiện nay hai chế độ này như nhau): bước kiểm không còn là bước kiểm chính của loại lỗi. Bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Nếu một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra chất lượng tự động của code cảnh báo rằng loại lỗi đó không còn gì canh giữ.", "when": "Nâng lên enforce khi giai đoạn shadow cho thấy kết quả đúng; hạ xuống khi người duyệt liên tục bác kết quả của nó. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu.", "example": "Với mặc định enforce: bước kiểm này được đánh dấu là bước kiểm chính của loại lỗi."}}},
{"key": "cis.quality_detectors.struct_truncated.missing_field", "label": "Quality check mode: missing field (cut-off text)", "guide": {"en": {"what": "The check that flags a required field left empty on catalogue tour rewrites and agency tour rewrites (a code check against the source's day plan, no AI cost). It belongs to the error type \"Cut-off text\": a field cut off mid-sentence, or a required field left empty. This setting only marks whether the check is a main (owner) check of that error type. Today it changes nothing about a piece, its score, a hold, a report or an evaluation. Its only effect: when a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "raise": "enforce (the stricter choice): the check is marked as a main check of its error type, the one the team relies on for that type. Nothing about a piece, its score, a hold, a report or an evaluation changes today. Only do it once its findings have proved right.", "lower": "warn or shadow (the looser choices; today the two behave the same): the check is no longer a main check of its error type. Nothing about a piece, its score, a hold, a report or an evaluation changes. If a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "when": "Promote it to enforce when a shadow period shows its findings are right; demote it when reviewers keep overruling its findings. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces.", "example": "With the default enforce: this check is marked as a main check of its error type."}, "vi": {"what": "Bước kiểm phát hiện một trường bắt buộc bị bỏ trống trên bản viết lại tour của catalogue và bản viết lại tour cho đại lý (bước code so với lịch trình ngày của nguồn, không tốn phí AI). Bước này thuộc loại lỗi \"Văn bản bị cắt\": một trường bị cắt giữa câu, hoặc một trường bắt buộc bị bỏ trống. Thiết lập này chỉ đánh dấu bước kiểm có phải bước kiểm chính (owner) của loại lỗi đó không. Hiện nay nó không đổi gì ở bài viết, điểm, việc giữ bài, báo cáo hay đánh giá. Tác dụng duy nhất: khi một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra tự động của code cảnh báo loại lỗi đó không còn gì canh giữ.", "raise": "enforce (lựa chọn chặt hơn): bước kiểm được đánh dấu là bước kiểm chính của loại lỗi, bước mà nhóm dựa vào cho loại lỗi đó. Hiện nay bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Chỉ nên đổi khi kết quả của bước kiểm đã được chứng minh là đúng.", "lower": "warn hoặc shadow (các lựa chọn nới hơn; hiện nay hai chế độ này như nhau): bước kiểm không còn là bước kiểm chính của loại lỗi. Bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Nếu một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra chất lượng tự động của code cảnh báo rằng loại lỗi đó không còn gì canh giữ.", "when": "Nâng lên enforce khi giai đoạn shadow cho thấy kết quả đúng; hạ xuống khi người duyệt liên tục bác kết quả của nó. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu.", "example": "Với mặc định enforce: bước kiểm này được đánh dấu là bước kiểm chính của loại lỗi."}}},
{"key": "cis.quality_detectors.struct_truncated.repair_contract", "label": "Quality check mode: repair limits (cut-off text)", "guide": {"en": {"what": "The check that flags an automatic repair that broke its limits (added a new fact, cut text, dropped a day or left the scope) on catalogue tour rewrites (a fixed rule in code, no AI cost). It belongs to the error type \"Cut-off text\": a field cut off mid-sentence, or a required field left empty. This setting only marks whether the check is a main (owner) check of that error type. Today it changes nothing about a piece, its score, a hold, a report or an evaluation. Its only effect: when a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "raise": "enforce (the stricter choice): the check is marked as a main check of its error type, the one the team relies on for that type. Nothing about a piece, its score, a hold, a report or an evaluation changes today. Only do it once its findings have proved right.", "lower": "warn or shadow (the looser choices; today the two behave the same): the check is no longer a main check of its error type. Nothing about a piece, its score, a hold, a report or an evaluation changes. If a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "when": "Promote it to enforce when a shadow period shows its findings are right; demote it when reviewers keep overruling its findings. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces.", "example": "With the default shadow: this check is not a main check of its error type; what it finds is handled by the check itself, as before."}, "vi": {"what": "Bước kiểm phát hiện một lần sửa tự động vượt giới hạn (thêm dữ kiện mới, cắt chữ, bỏ ngày hay ra ngoài phạm vi) trên bản viết lại tour của catalogue (quy tắc cố định trong code, không tốn phí AI). Bước này thuộc loại lỗi \"Văn bản bị cắt\": một trường bị cắt giữa câu, hoặc một trường bắt buộc bị bỏ trống. Thiết lập này chỉ đánh dấu bước kiểm có phải bước kiểm chính (owner) của loại lỗi đó không. Hiện nay nó không đổi gì ở bài viết, điểm, việc giữ bài, báo cáo hay đánh giá. Tác dụng duy nhất: khi một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra tự động của code cảnh báo loại lỗi đó không còn gì canh giữ.", "raise": "enforce (lựa chọn chặt hơn): bước kiểm được đánh dấu là bước kiểm chính của loại lỗi, bước mà nhóm dựa vào cho loại lỗi đó. Hiện nay bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Chỉ nên đổi khi kết quả của bước kiểm đã được chứng minh là đúng.", "lower": "warn hoặc shadow (các lựa chọn nới hơn; hiện nay hai chế độ này như nhau): bước kiểm không còn là bước kiểm chính của loại lỗi. Bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Nếu một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra chất lượng tự động của code cảnh báo rằng loại lỗi đó không còn gì canh giữ.", "when": "Nâng lên enforce khi giai đoạn shadow cho thấy kết quả đúng; hạ xuống khi người duyệt liên tục bác kết quả của nó. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu.", "example": "Với mặc định shadow: bước kiểm này không phải bước kiểm chính của loại lỗi; những gì nó phát hiện vẫn do chính bước kiểm xử lý như trước."}}},
{"key": "cis.quality_detectors.struct_truncated.text_truncated", "label": "Quality check mode: field cut off mid-sentence (cut-off text)", "guide": {"en": {"what": "The check that flags a text field cut off mid-sentence on catalogue tour rewrites (a fixed rule in code, no AI cost). It belongs to the error type \"Cut-off text\": a field cut off mid-sentence, or a required field left empty. This setting only marks whether the check is a main (owner) check of that error type. Today it changes nothing about a piece, its score, a hold, a report or an evaluation. Its only effect: when a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "raise": "enforce (the stricter choice): the check is marked as a main check of its error type, the one the team relies on for that type. Nothing about a piece, its score, a hold, a report or an evaluation changes today. Only do it once its findings have proved right.", "lower": "warn or shadow (the looser choices; today the two behave the same): the check is no longer a main check of its error type. Nothing about a piece, its score, a hold, a report or an evaluation changes. If a serious error type has no check left on enforce, the automatic quality check of the code warns that nothing guards that type.", "when": "Promote it to enforce when a shadow period shows its findings are right; demote it when reviewers keep overruling its findings. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces.", "example": "With the default shadow: this check is not a main check of its error type; what it finds is handled by the check itself, as before."}, "vi": {"what": "Bước kiểm phát hiện một trường văn bản bị cắt giữa câu trên bản viết lại tour của catalogue (quy tắc cố định trong code, không tốn phí AI). Bước này thuộc loại lỗi \"Văn bản bị cắt\": một trường bị cắt giữa câu, hoặc một trường bắt buộc bị bỏ trống. Thiết lập này chỉ đánh dấu bước kiểm có phải bước kiểm chính (owner) của loại lỗi đó không. Hiện nay nó không đổi gì ở bài viết, điểm, việc giữ bài, báo cáo hay đánh giá. Tác dụng duy nhất: khi một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra tự động của code cảnh báo loại lỗi đó không còn gì canh giữ.", "raise": "enforce (lựa chọn chặt hơn): bước kiểm được đánh dấu là bước kiểm chính của loại lỗi, bước mà nhóm dựa vào cho loại lỗi đó. Hiện nay bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Chỉ nên đổi khi kết quả của bước kiểm đã được chứng minh là đúng.", "lower": "warn hoặc shadow (các lựa chọn nới hơn; hiện nay hai chế độ này như nhau): bước kiểm không còn là bước kiểm chính của loại lỗi. Bài viết, điểm, việc giữ bài, báo cáo và kết quả đánh giá không đổi gì. Nếu một loại lỗi nghiêm trọng không còn bước kiểm nào ở enforce, bước kiểm tra chất lượng tự động của code cảnh báo rằng loại lỗi đó không còn gì canh giữ.", "when": "Nâng lên enforce khi giai đoạn shadow cho thấy kết quả đúng; hạ xuống khi người duyệt liên tục bác kết quả của nó. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu.", "example": "Với mặc định shadow: bước kiểm này không phải bước kiểm chính của loại lỗi; những gì nó phát hiện vẫn do chính bước kiểm xử lý như trước."}}},
{"key": "cis.quality_modes.t10_adjudicate", "label": "Second-opinion judge: mode of every kind", "guide": {"en": {"what": "A paid AI judge that takes a second look at four kinds of findings of the free checks (a leaked naming note, a repeat in other words, a FAQ answer that does not answer, a superlative with no scope) and decides whether they are real. This sets the mode of every kind whose own setting is inherit. off: no call. shadow: its verdicts are recorded only. repair: a confirmed finding gets one sentence repair, never a hold. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "repair (the stricter choice): confirmed findings are repaired; paid judge calls start.", "lower": "off or shadow (the looser choices): no repair; off makes no paid call, shadow pays for calls to measure the judge.", "when": "Use shadow to measure the judge before trusting it, then repair when its verdicts prove right. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default off: no second-opinion call is made."}, "vi": {"what": "Một giám khảo AI có phí xem lại bốn kiểu phát hiện của các bước kiểm miễn phí (lộ ghi chú cách gọi tên, lặp ý bằng lời khác, câu trả lời FAQ lạc đề, khen tột bậc không phạm vi) và quyết định có đúng là lỗi không. Thiết lập này đặt chế độ cho mọi kiểu có thiết lập riêng là inherit. off: không gọi. shadow: chỉ ghi lại kết luận. repair: phát hiện được xác nhận sẽ được sửa một câu, không giữ bài. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "repair (lựa chọn chặt hơn): phát hiện được xác nhận sẽ được sửa; bắt đầu có lượt gọi giám khảo có phí.", "lower": "off hoặc shadow (lựa chọn nới hơn): không sửa; off không gọi có phí, shadow trả phí để đo giám khảo.", "when": "Dùng shadow để đo giám khảo trước khi tin, rồi chuyển sang repair khi kết luận được chứng minh đúng. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định off: không có lượt gọi xem lại nào."}}},
{"key": "cis.quality_modes.t10_adjudicate_faq_non_answer", "label": "Second-opinion judge: FAQ answer that does not answer", "guide": {"en": {"what": "The mode for one kind of finding, a FAQ answer that does not answer its question. inherit = follow the second-opinion judge setting for every kind; or pick off, shadow or repair for this kind alone. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, câu trả lời FAQ không trả lời đúng câu hỏi. inherit = theo thiết lập chung của nhóm (giám khảo xem lại); hoặc chọn off, shadow or repair cho riêng kiểu này. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_adjudicate_naming_note_leak", "label": "Second-opinion judge: naming note leak", "guide": {"en": {"what": "The mode for one kind of finding, a naming note (how to spell or call a place) that leaked into the text. inherit = follow the second-opinion judge setting for every kind; or pick off, shadow or repair for this kind alone. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, ghi chú về cách viết hay cách gọi tên địa danh lọt vào bài. inherit = theo thiết lập chung của nhóm (giám khảo xem lại); hoặc chọn off, shadow or repair cho riêng kiểu này. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_adjudicate_paraphrased_repeat", "label": "Second-opinion judge: repeat in other words", "guide": {"en": {"what": "The mode for one kind of finding, the same point said twice in different words. inherit = follow the second-opinion judge setting for every kind; or pick off, shadow or repair for this kind alone. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, cùng một ý được nói hai lần bằng lời khác nhau. inherit = theo thiết lập chung của nhóm (giám khảo xem lại); hoặc chọn off, shadow or repair cho riêng kiểu này. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_adjudicate_scopeless_superlative", "label": "Second-opinion judge: superlative with no scope", "guide": {"en": {"what": "The mode for one kind of finding, a superlative with no scope (the best, the most beautiful) that the source does not support. inherit = follow the second-opinion judge setting for every kind; or pick off, shadow or repair for this kind alone. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, lời khen tột bậc không nêu phạm vi (đẹp nhất, tuyệt nhất) mà nguồn không chứng minh. inherit = theo thiết lập chung của nhóm (giám khảo xem lại); hoặc chọn off, shadow or repair cho riêng kiểu này. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_f12_scope", "label": "Content checks: place outside the piece's scope", "guide": {"en": {"what": "What the free scope check does when a blog or social post names a place outside the piece's scope (a place no day of the trip visits). warn: reported only. block: a finding in the body gets one sentence repair, and the piece is held if it is still there. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "block (the stricter choice): pieces stop naming places the trip does not visit; more repairs (paid) and holds.", "lower": "warn (the looser choice): the piece goes on with a flag.", "when": "Choose block when tenants receive pieces that send readers to places the tour never visits. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default warn: out-of-scope places are flagged, nothing is held."}, "vi": {"what": "Bước kiểm phạm vi (miễn phí) xử lý ra sao khi bài blog hay mạng xã hội nêu một địa điểm ngoài phạm vi của bài (nơi không ngày nào của chuyến ghé). warn: chỉ báo. block: lỗi trong thân bài được sửa một câu, nếu vẫn còn thì bài bị giữ. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "block (lựa chọn chặt hơn): bài không còn nhắc nơi chuyến đi không ghé; nhiều lần sửa (có phí) và giữ bài hơn.", "lower": "warn (lựa chọn nới hơn): bài đi tiếp kèm cờ.", "when": "Chọn block khi đại lý nhận bài dẫn người đọc tới nơi tour không hề ghé. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định warn: địa điểm ngoài phạm vi được gắn cờ, không giữ bài."}}},
{"key": "cis.quality_modes.t10_f14_floor", "label": "Content checks: social post under its minimum length", "guide": {"en": {"what": "What happens when a social post comes out shorter than its channel's minimum. repair: the post is rewritten once (a paid call). warn: reported only, the switch to stop those rewrites. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "repair (the stricter choice): short posts are lengthened once before delivery; one more paid call each.", "lower": "warn (the looser choice): short posts go out as written, with a flag.", "when": "Choose warn if the rewrites misbehave (for example they add facts) or cost too much; repair otherwise. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default repair: a too-short post is rewritten once."}, "vi": {"what": "Xử lý ra sao khi bài mạng xã hội ngắn hơn mức tối thiểu của kênh. repair: viết lại bài một lần (lượt gọi có phí). warn: chỉ báo, là công tắc để dừng các lần viết lại đó. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "repair (lựa chọn chặt hơn): bài quá ngắn được kéo dài một lần trước khi giao; thêm một lượt gọi có phí mỗi bài.", "lower": "warn (lựa chọn nới hơn): bài ngắn được giao nguyên trạng, kèm cờ.", "when": "Chọn warn nếu lần viết lại hoạt động sai (ví dụ thêm dữ kiện) hoặc quá tốn; còn lại để repair. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định repair: bài quá ngắn được viết lại một lần."}}},
{"key": "cis.quality_modes.t10_f9_brand_style", "label": "Content checks: off-brand wording", "guide": {"en": {"what": "What happens when the AI judge finds off-brand or AI-sounding wording in a blog or social post. warn: reported only. repair: on the first attempt, a flagged sentence gets one sentence repair (never a hold). An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "repair (the stricter choice): flagged sentences are rewritten once; one more paid call per flagged piece.", "lower": "warn (the looser choice): the wording stays, staff see a flag.", "when": "Choose repair when tenants keep editing out wording the judge already flagged. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default warn: flagged wording is listed, not changed."}, "vi": {"what": "Xử lý ra sao khi giám khảo AI thấy câu chữ lệch thương hiệu hoặc nghe như máy viết trong bài blog hay mạng xã hội. warn: chỉ báo. repair: ở lần viết đầu, câu bị gắn cờ được sửa một lần (không bao giờ giữ bài). Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "repair (lựa chọn chặt hơn): câu bị gắn cờ được viết lại một lần; thêm một lượt gọi có phí mỗi bài bị gắn cờ.", "lower": "warn (lựa chọn nới hơn): câu chữ giữ nguyên, nhân viên thấy cờ.", "when": "Chọn repair khi đại lý liên tục tự sửa những câu giám khảo đã gắn cờ. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định warn: câu bị gắn cờ được liệt kê, không bị sửa."}}},
{"key": "cis.quality_modes.t10_f9_policy", "label": "Claim judge policy", "guide": {"en": {"what": "Which policy the AI claim judge of blog and social posts follows. interim: only a trip promise the source lacks holds a piece; every other kind of finding follows its own claim setting on this page (warn by default). legacy: the older rule in which most findings held the piece, kept as a rollback. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "legacy (the stricter choice): far more pieces are held, including for claims the writing policy allows.", "lower": "interim (the looser choice): only trip promises hold; the rest are flags.", "when": "Switch to legacy only to roll back if the interim policy lets harmful claims through, or briefly to compare. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default interim: a blog that promises a sunrise view the source lacks is held; place background only gets a flag."}, "vi": {"what": "Giám khảo khẳng định (AI) của bài blog và mạng xã hội theo chính sách nào. interim: chỉ lời hứa chuyến đi không có trong nguồn mới giữ bài; các loại phát hiện khác theo thiết lập khẳng định riêng trên trang này (mặc định warn). legacy: quy tắc cũ, hầu hết phát hiện đều giữ bài, giữ lại để quay về khi cần. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "legacy (lựa chọn chặt hơn): nhiều bài bị giữ hơn hẳn, kể cả vì khẳng định chính sách viết cho phép.", "lower": "interim (lựa chọn nới hơn): chỉ lời hứa chuyến đi giữ bài; còn lại là cờ.", "when": "Chỉ chuyển sang legacy để quay về nếu chính sách interim để lọt khẳng định có hại, hoặc tạm thời để so sánh. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định interim: bài blog hứa cảnh bình minh mà nguồn không có sẽ bị giữ; bối cảnh địa danh chỉ bị gắn cờ."}}},
{"key": "cis.quality_modes.t10_seed_align", "label": "Source match checks: mode of every kind", "guide": {"en": {"what": "Free checks that compare a blog or social post with its source material and flag ten kinds of drift (an optional activity written as planned, 'near' written as 'at', a leaked brief line ...). This sets the mode of every kind whose own setting is inherit. off: they do not run. shadow: findings are recorded only. repair: a finding gets one sentence repair, never a hold. hold: like repair, and a kind promoted to a fact error may hold the piece. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "repair or hold (the stricter choices): drift from the source is repaired (a paid call per finding) and, on hold, may stop a piece.", "lower": "off or shadow (the looser choices): no repair; shadow still records what would have been found.", "when": "Move to shadow to measure the checks on real pieces, then to repair when their findings prove right. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default off: the checks do not run."}, "vi": {"what": "Các bước kiểm miễn phí so bài blog hay mạng xã hội với tư liệu nguồn và gắn cờ mười kiểu lệch (hoạt động tuỳ chọn viết như đã lên lịch, 'gần' viết thành 'tại', lộ câu của brief ...). Thiết lập này đặt chế độ cho mọi kiểu có thiết lập riêng là inherit. off: không chạy. shadow: chỉ ghi lại. repair: mỗi phát hiện được sửa một câu, không giữ bài. hold: như repair, và kiểu đã được nâng thành lỗi dữ kiện có thể giữ bài. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "repair hoặc hold (lựa chọn chặt hơn): phần lệch khỏi nguồn được sửa (mỗi phát hiện một lượt gọi có phí) và, ở hold, có thể chặn bài.", "lower": "off hoặc shadow (lựa chọn nới hơn): không sửa; shadow vẫn ghi lại những gì lẽ ra đã phát hiện.", "when": "Chuyển sang shadow để đo các bước kiểm trên bài thật, rồi sang repair khi kết quả được chứng minh đúng. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định off: các bước kiểm không chạy."}}},
{"key": "cis.quality_modes.t10_seed_align_brief_recipe_leak", "label": "Source match checks: writing brief leak", "guide": {"en": {"what": "The mode for one kind of finding, wording of the writing brief that leaked into the text. inherit = follow the source match checks setting for every kind; or pick off, shadow, repair or hold for this kind alone. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, câu chữ của brief viết lọt vào bài. inherit = theo thiết lập chung của nhóm (kiểm khớp nguồn); hoặc chọn off, shadow, repair or hold cho riêng kiểu này. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_seed_align_difficulty_promise", "label": "Source match checks: difficulty promise", "guide": {"en": {"what": "The mode for one kind of finding, a promise about how easy or hard the trip is that the source does not make. inherit = follow the source match checks setting for every kind; or pick off, shadow, repair or hold for this kind alone. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, lời hứa về độ dễ hay khó của chuyến đi mà nguồn không nêu. inherit = theo thiết lập chung của nhóm (kiểm khớp nguồn); hoặc chọn off, shadow, repair or hold cho riêng kiểu này. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_seed_align_naming_note_leak", "label": "Source match checks: naming note leak", "guide": {"en": {"what": "The mode for one kind of finding, a naming note (how to spell or call a place) that leaked into the text. inherit = follow the source match checks setting for every kind; or pick off, shadow, repair or hold for this kind alone. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, ghi chú về cách viết hay cách gọi tên địa danh lọt vào bài. inherit = theo thiết lập chung của nhóm (kiểm khớp nguồn); hoặc chọn off, shadow, repair or hold cho riêng kiểu này. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_seed_align_near_as_at", "label": "Source match checks: 'near' written as 'at'", "guide": {"en": {"what": "The mode for one kind of finding, a stay or visit near a place written as being at the place. inherit = follow the source match checks setting for every kind; or pick off, shadow, repair or hold for this kind alone. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, nơi ở hay điểm ghé gần một địa danh bị viết thành nằm tại địa danh đó. inherit = theo thiết lập chung của nhóm (kiểm khớp nguồn); hoặc chọn off, shadow, repair or hold cho riêng kiểu này. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_seed_align_optional_as_planned", "label": "Source match checks: optional activity written as planned", "guide": {"en": {"what": "The mode for one kind of finding, an optional activity written as if it is part of the plan. inherit = follow the source match checks setting for every kind; or pick off, shadow, repair or hold for this kind alone. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, hoạt động tuỳ chọn được viết như thể nằm trong kế hoạch. inherit = theo thiết lập chung của nhóm (kiểm khớp nguồn); hoặc chọn off, shadow, repair or hold cho riêng kiểu này. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_seed_align_orphan_opener", "label": "Source match checks: opener with nothing before it", "guide": {"en": {"what": "The mode for one kind of finding, an opening line that refers to something never introduced. inherit = follow the source match checks setting for every kind; or pick off, shadow, repair or hold for this kind alone. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, câu mở đầu nhắc tới điều chưa từng được giới thiệu. inherit = theo thiết lập chung của nhóm (kiểm khớp nguồn); hoặc chọn off, shadow, repair or hold cho riêng kiểu này. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_seed_align_paraphrased_repeat", "label": "Source match checks: repeat in other words", "guide": {"en": {"what": "The mode for one kind of finding, the same point said twice in different words. inherit = follow the source match checks setting for every kind; or pick off, shadow, repair or hold for this kind alone. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, cùng một ý được nói hai lần bằng lời khác nhau. inherit = theo thiết lập chung của nhóm (kiểm khớp nguồn); hoặc chọn off, shadow, repair or hold cho riêng kiểu này. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_seed_align_planned_as_optional", "label": "Source match checks: planned activity written as optional", "guide": {"en": {"what": "The mode for one kind of finding, a planned activity written as if it were optional. inherit = follow the source match checks setting for every kind; or pick off, shadow, repair or hold for this kind alone. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, hoạt động có trong kế hoạch lại được viết như thể tuỳ chọn. inherit = theo thiết lập chung của nhóm (kiểm khớp nguồn); hoặc chọn off, shadow, repair or hold cho riêng kiểu này. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_seed_align_scopeless_superlative", "label": "Source match checks: superlative with no scope", "guide": {"en": {"what": "The mode for one kind of finding, a superlative with no scope (the best, the most beautiful) that the source does not support. inherit = follow the source match checks setting for every kind; or pick off, shadow, repair or hold for this kind alone. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, lời khen tột bậc không nêu phạm vi (đẹp nhất, tuyệt nhất) mà nguồn không chứng minh. inherit = theo thiết lập chung của nhóm (kiểm khớp nguồn); hoặc chọn off, shadow, repair or hold cho riêng kiểu này. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_seed_align_world_share_unsupported", "label": "Source match checks: unsupported world claim", "guide": {"en": {"what": "The mode for one kind of finding, a world-ranking or share-of-the-world claim the source does not support (home to half the world's ...). inherit = follow the source match checks setting for every kind; or pick off, shadow, repair or hold for this kind alone. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, khẳng định xếp hạng thế giới hay tỷ lệ của thế giới mà nguồn không chứng minh (nơi có một nửa số ... của thế giới). inherit = theo thiết lập chung của nhóm (kiểm khớp nguồn); hoặc chọn off, shadow, repair or hold cho riêng kiểu này. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t2_judge_gate", "label": "Agency rewrite: which score decides pass or review", "guide": {"en": {"what": "Which score decides whether an agency's tour rewrite passes or is marked for review. brand_fit: brand fit alone (the mission is only logged). brand_fit_mission: brand fit, capped under the pass line when the agency's mission is missing. combined: the older mixed score.", "raise": "brand_fit_mission (the stricter choice): versions that miss the agency's mission are marked for review.", "lower": "brand_fit (the looser choice): the mission does not change the verdict; combined is the older rule.", "when": "Choose brand_fit_mission when agencies complain that versions ignore their mission. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default brand_fit: a version that fits the brand passes even if the mission does not show."}, "vi": {"what": "Điểm nào quyết định bản viết lại tour cho đại lý đạt hay bị đánh dấu cần duyệt. brand_fit: chỉ độ hợp thương hiệu (sứ mệnh chỉ được ghi lại). brand_fit_mission: độ hợp thương hiệu, bị giới hạn dưới ngưỡng đạt khi thiếu sứ mệnh của đại lý. combined: điểm tổng hợp kiểu cũ.", "raise": "brand_fit_mission (lựa chọn chặt hơn): phiên bản thiếu sứ mệnh của đại lý bị đánh dấu cần duyệt.", "lower": "brand_fit (lựa chọn nới hơn): sứ mệnh không ảnh hưởng kết luận; combined là quy tắc cũ.", "when": "Chọn brand_fit_mission khi đại lý phàn nàn phiên bản bỏ qua sứ mệnh của họ. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định brand_fit: phiên bản hợp thương hiệu là đạt dù không thể hiện sứ mệnh."}}},
{"key": "cis.quality_modes.t3_background_facts", "label": "Agency rewrite fact check: accept place background", "guide": {"en": {"what": "On: the fact check of an agency's tour rewrite accepts background about named places (the year a temple was built, a century, a peak's height) even when the catalogue tour does not give it. Trip activities, services and times the source lacks are never accepted. Off: every such number is flagged.", "raise": "On: richer place background is allowed; a wrong background fact may get through.", "lower": "Off: any year, century or height not in the tour is flagged as a number not in the source; more versions marked for review.", "when": "Turn it off if wrong background facts reach agencies; keep it on while reviewers accept them. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default on: a rewrite saying a pagoda dates from the 11th century passes the number check."}, "vi": {"what": "Bật: bước kiểm dữ kiện của bản viết lại tour cho đại lý chấp nhận thông tin bối cảnh về địa danh (năm xây đền, thế kỷ, độ cao đỉnh núi) dù tour gốc của catalogue không nêu. Hoạt động, dịch vụ và giờ giấc của chuyến mà nguồn không có thì không bao giờ được chấp nhận. Tắt: mọi con số như vậy đều bị gắn cờ.", "raise": "Bật: cho phép bối cảnh địa danh phong phú hơn; một dữ kiện bối cảnh sai có thể lọt qua.", "lower": "Tắt: mọi năm, thế kỷ hay độ cao không có trong tour đều bị gắn cờ là con số không có trong nguồn; nhiều phiên bản bị đánh dấu cần duyệt hơn.", "when": "Tắt nếu dữ kiện bối cảnh sai đến tay đại lý; giữ bật khi người duyệt chấp nhận chúng. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định on: bản viết lại nói ngôi chùa có từ thế kỷ 11 vẫn qua bước kiểm con số."}}},
{"key": "cis.quality_modes.t7_debate", "label": "Topic planning: what to do with contested topics", "guide": {"en": {"what": "When topics are proposed for a channel, a topic whose keyword is too contested (see the contested threshold) is flagged. rank: flagged topics are listed after the others, none dropped. cut: flagged topics are dropped, worst first, up to the cut share. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "cut (the stricter choice): fewer contested topics are proposed; a channel's list gets shorter.", "lower": "rank (the looser choice): every topic stays on the list; contested ones come last.", "when": "Choose cut when tenants keep getting topics they cannot rank for. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default rank: contested topics stay, at the end of the list."}, "vi": {"what": "Khi đề xuất chủ đề cho một kênh, chủ đề có từ khoá quá cạnh tranh (xem ngưỡng cạnh tranh) bị gắn cờ. rank: chủ đề bị gắn cờ xếp sau các chủ đề khác, không bỏ cái nào. cut: chủ đề bị gắn cờ bị loại, tệ nhất trước, tới tỷ lệ loại tối đa. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "cut (lựa chọn chặt hơn): ít chủ đề cạnh tranh được đề xuất hơn; danh sách của kênh ngắn lại.", "lower": "rank (lựa chọn nới hơn): mọi chủ đề vẫn trong danh sách; chủ đề cạnh tranh nằm cuối.", "when": "Chọn cut khi đại lý liên tục nhận chủ đề khó lên thứ hạng tìm kiếm. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định rank: chủ đề cạnh tranh vẫn còn, ở cuối danh sách."}}},
{"key": "cis.quality_modes.t9_brief_grounding", "label": "Content writer: drop brief lines the source does not support", "guide": {"en": {"what": "Before the blog and social writer sees its angle brief, the brief can be checked against the source. off: the brief goes to the writer as written. r9: lines of the brief the source does not support are dropped first, so the writer is not asked to write them. An emergency switch on the server can still override it for one release (a badge on this page shows it).", "raise": "r9 (the stricter choice): fewer invented details reach the writer; a brief may lose a line it needed.", "lower": "off (the looser choice): the writer gets the whole brief, unsupported lines included.", "when": "Choose r9 when held pieces trace back to a brief that asked for something the source lacks. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default off: the brief goes to the writer unchanged."}, "vi": {"what": "Trước khi bộ viết blog và mạng xã hội nhận brief góc nhìn, brief có thể được đối chiếu với nguồn. off: brief được giao nguyên văn. r9: các dòng của brief mà nguồn không chứng minh bị bỏ trước, để bộ viết không bị yêu cầu viết chúng. Một công tắc khẩn trên máy chủ vẫn có thể ghi đè trong một bản phát hành (huy hiệu trên trang sẽ hiện).", "raise": "r9 (lựa chọn chặt hơn): ít chi tiết bịa đến tay bộ viết hơn; brief có thể mất một dòng cần thiết.", "lower": "off (lựa chọn nới hơn): bộ viết nhận toàn bộ brief, kể cả dòng không có căn cứ.", "when": "Chọn r9 khi các bài bị giữ đều bắt nguồn từ brief yêu cầu điều nguồn không có. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định off: brief được giao cho bộ viết nguyên vẹn."}}},
{"key": "cis.retention.job_failed_days", "label": "Failed jobs: days kept", "guide": {"en": {"what": "Days a failed, cancelled or budget-stopped background job is kept before it is archived to S3 and removed from the job list.", "raise": "Failures stay in the job pages longer for investigation; the job table grows.", "lower": "Failures leave the pages sooner; older ones are only in the archive.", "when": "Change it when investigations need older failures in the pages (raise it).", "example": "With the default of 90 days."}, "vi": {"what": "Số ngày một job nền bị lỗi, bị huỷ hoặc dừng vì hết ngân sách được giữ trước khi lưu trữ sang S3 và gỡ khỏi danh sách job.", "raise": "Job lỗi nằm trên các trang job lâu hơn để điều tra; bảng job lớn dần.", "lower": "Job lỗi rời các trang sớm hơn; job cũ chỉ còn trong kho lưu trữ.", "when": "Đổi khi việc điều tra cần xem job lỗi cũ hơn trên trang (nâng lên).", "example": "Với mặc định 90 ngày."}}},
{"key": "cis.retention.job_succeeded_days", "label": "Finished jobs: days kept", "guide": {"en": {"what": "Days a background job that finished well stays in the job list before it is deleted (no archive).", "raise": "Finished jobs stay visible in the job pages longer; the job table grows.", "lower": "The job table stays small; finished jobs disappear from the pages sooner.", "when": "Change it when you need to look back further at finished jobs (raise it).", "example": "With the default of 30 days."}, "vi": {"what": "Số ngày một job nền chạy thành công còn nằm trong danh sách job trước khi bị xoá (không lưu trữ).", "raise": "Job đã xong hiển thị lâu hơn trên các trang job; bảng job lớn dần.", "lower": "Bảng job gọn; job đã xong biến khỏi các trang sớm hơn.", "when": "Đổi khi cần xem lại job đã xong lâu hơn (nâng lên).", "example": "Với mặc định 30 ngày."}}},
{"key": "cis.retention.llm_call_log_days", "label": "AI call log: days kept in full", "guide": {"en": {"what": "Days each AI call row (model, cost, stage) is kept in full. Older rows are archived to S3 and rolled up per day, so cost reports still add up but single calls can no longer be opened. After a change the next scheduled run is a dry run first.", "raise": "Single calls stay inspectable longer; the database grows.", "lower": "The database stays smaller; old single calls are only in the archive.", "when": "Change it when cost investigations need older single calls (raise it), or when the table grows too large (lower it).", "example": "With the default of 180 days."}, "vi": {"what": "Số ngày mỗi dòng ghi một lần gọi AI (model, chi phí, công đoạn) được giữ đầy đủ. Dòng cũ hơn được lưu trữ sang S3 và gộp theo ngày, nên báo cáo chi phí vẫn khớp nhưng không mở được từng lần gọi nữa. Sau khi đổi, lần chạy theo lịch kế tiếp sẽ chạy thử (dry run) trước.", "raise": "Từng lần gọi được xem lại lâu hơn; cơ sở dữ liệu lớn dần.", "lower": "Cơ sở dữ liệu nhỏ hơn; lần gọi cũ chỉ còn trong kho lưu trữ.", "when": "Đổi khi việc điều tra chi phí cần các lần gọi cũ hơn (nâng lên), hoặc khi bảng quá lớn (hạ xuống).", "example": "Với mặc định 180 ngày."}}},
{"key": "cis.retention.tenant_api_usage_days", "label": "Tenant API usage log: days kept in full", "guide": {"en": {"what": "Days each row of a tenant's API usage is kept in full. Older rows are archived and rolled up per month, so monthly usage still adds up.", "raise": "Daily API usage stays visible longer; the database grows.", "lower": "The database stays smaller; old daily detail is only in the archive.", "when": "Change it when support needs older daily usage of a tenant (raise it), or when the table grows too large (lower it).", "example": "With the default of 90 days."}, "vi": {"what": "Số ngày mỗi dòng ghi lượt dùng API của tenant được giữ đầy đủ. Dòng cũ hơn được lưu trữ và gộp theo tháng, nên số liệu hằng tháng vẫn khớp.", "raise": "Chi tiết dùng API theo ngày được xem lâu hơn; cơ sở dữ liệu lớn dần.", "lower": "Cơ sở dữ liệu nhỏ hơn; chi tiết theo ngày cũ chỉ còn trong kho lưu trữ.", "when": "Đổi khi bộ phận hỗ trợ cần chi tiết theo ngày cũ hơn của một tenant (nâng lên), hoặc khi bảng quá lớn (hạ xuống).", "example": "Với mặc định 90 ngày."}}},
{"key": "cis.seo.aim_s1_meta_max", "label": "Search description target, catalogue rewrite (current writer): high end", "guide": {"en": {"what": "The upper end of the search description length the catalogue rewrite (current writer) is asked to write, in characters. Writers are asked for a little less than the band because a model overshoots a character target; code then fits the text into the band. It must not pass the band's longest. Shown for reference only: the page refuses a change for now, because the writers read this value when they start; a later release reads it on every call.", "raise": "The writer aims longer: fewer short texts, more trimming.", "lower": "The writer aims shorter: less trimming, more short texts to lengthen or refuse.", "when": "When many descriptions of this writer are trimmed (aim lower) or come out short (aim higher).", "example": "With the default of 148 characters: the writer is asked for at most 148."}, "vi": {"what": "Đầu trên của độ dài mô tả tìm kiếm mà bộ viết lại catalogue (bộ viết hiện tại) được yêu cầu viết, tính bằng ký tự. Bộ viết được yêu cầu viết hơi ngắn hơn khoảng chuẩn vì model hay viết vượt mục tiêu ký tự; sau đó code căn chữ vào khoảng chuẩn. Không được vượt mức dài nhất của khoảng. Hiện chỉ để xem: trang chưa cho đổi, vì các bộ viết chỉ đọc giá trị này lúc khởi động; một bản phát hành sau sẽ đọc lại ở mỗi lần gọi.", "raise": "Bộ viết nhắm dài hơn: ít chữ ngắn hơn, cắt nhiều hơn.", "lower": "Bộ viết nhắm ngắn hơn: ít phải cắt hơn, nhiều chữ ngắn phải kéo dài hoặc bị từ chối hơn.", "when": "Khi nhiều mô tả của bộ viết này bị cắt (nhắm thấp lại) hoặc bị ngắn (nhắm cao lên).", "example": "Với mặc định 148 ký tự: bộ viết được yêu cầu viết tối đa 148."}}},
{"key": "cis.seo.aim_s1_meta_min", "label": "Search description target, catalogue rewrite (current writer): low end", "guide": {"en": {"what": "The lower end of the search description length the catalogue rewrite (current writer) is asked to write, in characters. Writers are asked for a little less than the band because a model overshoots a character target; code then fits the text into the band. It may sit under the band's shortest: a code step lengthens a short text. Shown for reference only: the page refuses a change for now, because the writers read this value when they start; a later release reads it on every call.", "raise": "The writer aims longer: fewer short texts, more trimming.", "lower": "The writer aims shorter: less trimming, more short texts to lengthen or refuse.", "when": "When many descriptions of this writer are trimmed (aim lower) or come out short (aim higher).", "example": "With the default of 130 characters: the writer is asked for at least 130."}, "vi": {"what": "Đầu dưới của độ dài mô tả tìm kiếm mà bộ viết lại catalogue (bộ viết hiện tại) được yêu cầu viết, tính bằng ký tự. Bộ viết được yêu cầu viết hơi ngắn hơn khoảng chuẩn vì model hay viết vượt mục tiêu ký tự; sau đó code căn chữ vào khoảng chuẩn. Có thể thấp hơn mức ngắn nhất của khoảng: một bước code sẽ kéo dài chữ ngắn. Hiện chỉ để xem: trang chưa cho đổi, vì các bộ viết chỉ đọc giá trị này lúc khởi động; một bản phát hành sau sẽ đọc lại ở mỗi lần gọi.", "raise": "Bộ viết nhắm dài hơn: ít chữ ngắn hơn, cắt nhiều hơn.", "lower": "Bộ viết nhắm ngắn hơn: ít phải cắt hơn, nhiều chữ ngắn phải kéo dài hoặc bị từ chối hơn.", "when": "Khi nhiều mô tả của bộ viết này bị cắt (nhắm thấp lại) hoặc bị ngắn (nhắm cao lên).", "example": "Với mặc định 130 ký tự: bộ viết được yêu cầu viết ít nhất 130."}}},
{"key": "cis.seo.aim_t2_meta_max", "label": "Search description target, older catalogue writer and agency rewrite: high end", "guide": {"en": {"what": "The upper end of the search description length the older catalogue writer and agency rewrite is asked to write, in characters. Writers are asked for a little less than the band because a model overshoots a character target; code then fits the text into the band. It must not pass the band's longest. Shown for reference only: the page refuses a change for now, because the writers read this value when they start; a later release reads it on every call.", "raise": "The writer aims longer: fewer short texts, more trimming.", "lower": "The writer aims shorter: less trimming, more short texts to lengthen or refuse.", "when": "When many descriptions of this writer are trimmed (aim lower) or come out short (aim higher).", "example": "With the default of 152 characters: the writer is asked for at most 152."}, "vi": {"what": "Đầu trên của độ dài mô tả tìm kiếm mà bộ viết catalogue cũ và bản viết lại cho đại lý được yêu cầu viết, tính bằng ký tự. Bộ viết được yêu cầu viết hơi ngắn hơn khoảng chuẩn vì model hay viết vượt mục tiêu ký tự; sau đó code căn chữ vào khoảng chuẩn. Không được vượt mức dài nhất của khoảng. Hiện chỉ để xem: trang chưa cho đổi, vì các bộ viết chỉ đọc giá trị này lúc khởi động; một bản phát hành sau sẽ đọc lại ở mỗi lần gọi.", "raise": "Bộ viết nhắm dài hơn: ít chữ ngắn hơn, cắt nhiều hơn.", "lower": "Bộ viết nhắm ngắn hơn: ít phải cắt hơn, nhiều chữ ngắn phải kéo dài hoặc bị từ chối hơn.", "when": "Khi nhiều mô tả của bộ viết này bị cắt (nhắm thấp lại) hoặc bị ngắn (nhắm cao lên).", "example": "Với mặc định 152 ký tự: bộ viết được yêu cầu viết tối đa 152."}}},
{"key": "cis.seo.aim_t2_meta_min", "label": "Search description target, older catalogue writer and agency rewrite: low end", "guide": {"en": {"what": "The lower end of the search description length the older catalogue writer and agency rewrite is asked to write, in characters. Writers are asked for a little less than the band because a model overshoots a character target; code then fits the text into the band. It must not sit under the band's shortest (this writer has no lengthening step). Shown for reference only: the page refuses a change for now, because the writers read this value when they start; a later release reads it on every call.", "raise": "The writer aims longer: fewer short texts, more trimming.", "lower": "The writer aims shorter: less trimming, more short texts to lengthen or refuse.", "when": "When many descriptions of this writer are trimmed (aim lower) or come out short (aim higher).", "example": "With the default of 145 characters: the writer is asked for at least 145."}, "vi": {"what": "Đầu dưới của độ dài mô tả tìm kiếm mà bộ viết catalogue cũ và bản viết lại cho đại lý được yêu cầu viết, tính bằng ký tự. Bộ viết được yêu cầu viết hơi ngắn hơn khoảng chuẩn vì model hay viết vượt mục tiêu ký tự; sau đó code căn chữ vào khoảng chuẩn. Không được thấp hơn mức ngắn nhất (bộ viết này không có bước kéo dài). Hiện chỉ để xem: trang chưa cho đổi, vì các bộ viết chỉ đọc giá trị này lúc khởi động; một bản phát hành sau sẽ đọc lại ở mỗi lần gọi.", "raise": "Bộ viết nhắm dài hơn: ít chữ ngắn hơn, cắt nhiều hơn.", "lower": "Bộ viết nhắm ngắn hơn: ít phải cắt hơn, nhiều chữ ngắn phải kéo dài hoặc bị từ chối hơn.", "when": "Khi nhiều mô tả của bộ viết này bị cắt (nhắm thấp lại) hoặc bị ngắn (nhắm cao lên).", "example": "Với mặc định 145 ký tự: bộ viết được yêu cầu viết ít nhất 145."}}},
{"key": "cis.seo.aim_t9_meta_max", "label": "Search description target, blog and social writer, and the search fit step: high end", "guide": {"en": {"what": "The upper end of the search description length the blog and social writer, and the search fit step is asked to write, in characters. Writers are asked for a little less than the band because a model overshoots a character target; code then fits the text into the band. It must not pass the band's longest. Shown for reference only: the page refuses a change for now, because the writers read this value when they start; a later release reads it on every call.", "raise": "The writer aims longer: fewer short texts, more trimming.", "lower": "The writer aims shorter: less trimming, more short texts to lengthen or refuse.", "when": "When many descriptions of this writer are trimmed (aim lower) or come out short (aim higher).", "example": "With the default of 145 characters: the writer is asked for at most 145."}, "vi": {"what": "Đầu trên của độ dài mô tả tìm kiếm mà bộ viết blog và mạng xã hội, và bước căn chỉnh tìm kiếm được yêu cầu viết, tính bằng ký tự. Bộ viết được yêu cầu viết hơi ngắn hơn khoảng chuẩn vì model hay viết vượt mục tiêu ký tự; sau đó code căn chữ vào khoảng chuẩn. Không được vượt mức dài nhất của khoảng. Hiện chỉ để xem: trang chưa cho đổi, vì các bộ viết chỉ đọc giá trị này lúc khởi động; một bản phát hành sau sẽ đọc lại ở mỗi lần gọi.", "raise": "Bộ viết nhắm dài hơn: ít chữ ngắn hơn, cắt nhiều hơn.", "lower": "Bộ viết nhắm ngắn hơn: ít phải cắt hơn, nhiều chữ ngắn phải kéo dài hoặc bị từ chối hơn.", "when": "Khi nhiều mô tả của bộ viết này bị cắt (nhắm thấp lại) hoặc bị ngắn (nhắm cao lên).", "example": "Với mặc định 145 ký tự: bộ viết được yêu cầu viết tối đa 145."}}},
{"key": "cis.seo.aim_t9_meta_min", "label": "Search description target, blog and social writer, and the search fit step: low end", "guide": {"en": {"what": "The lower end of the search description length the blog and social writer, and the search fit step is asked to write, in characters. Writers are asked for a little less than the band because a model overshoots a character target; code then fits the text into the band. It may sit under the band's shortest: a code step lengthens a short text. Shown for reference only: the page refuses a change for now, because the writers read this value when they start; a later release reads it on every call.", "raise": "The writer aims longer: fewer short texts, more trimming.", "lower": "The writer aims shorter: less trimming, more short texts to lengthen or refuse.", "when": "When many descriptions of this writer are trimmed (aim lower) or come out short (aim higher).", "example": "With the default of 130 characters: the writer is asked for at least 130."}, "vi": {"what": "Đầu dưới của độ dài mô tả tìm kiếm mà bộ viết blog và mạng xã hội, và bước căn chỉnh tìm kiếm được yêu cầu viết, tính bằng ký tự. Bộ viết được yêu cầu viết hơi ngắn hơn khoảng chuẩn vì model hay viết vượt mục tiêu ký tự; sau đó code căn chữ vào khoảng chuẩn. Có thể thấp hơn mức ngắn nhất của khoảng: một bước code sẽ kéo dài chữ ngắn. Hiện chỉ để xem: trang chưa cho đổi, vì các bộ viết chỉ đọc giá trị này lúc khởi động; một bản phát hành sau sẽ đọc lại ở mỗi lần gọi.", "raise": "Bộ viết nhắm dài hơn: ít chữ ngắn hơn, cắt nhiều hơn.", "lower": "Bộ viết nhắm ngắn hơn: ít phải cắt hơn, nhiều chữ ngắn phải kéo dài hoặc bị từ chối hơn.", "when": "Khi nhiều mô tả của bộ viết này bị cắt (nhắm thấp lại) hoặc bị ngắn (nhắm cao lên).", "example": "Với mặc định 130 ký tự: bộ viết được yêu cầu viết ít nhất 130."}}},
{"key": "cis.seo.meta_max", "label": "Search description: longest", "guide": {"en": {"what": "The longest search description the checks accept, in characters; code trims a longer one at a word boundary. One band for every writer. Shown for reference only: the page refuses a change for now, because the writers read this value when they start; a later release reads it on every call.", "raise": "Longer text is allowed before it is trimmed; search engines may cut it on screen.", "lower": "Text is trimmed shorter; less room for the selling point.", "when": "When search engines change how much they show, or search reports show the text cut or too thin.", "example": "With the default of 155 characters: anything longer than 155 is trimmed."}, "vi": {"what": "Độ dài tối đa (ký tự) của mô tả tìm kiếm; code cắt bớt mô tả dài hơn tại ranh giới từ. Một khoảng chung cho mọi bộ viết. Hiện chỉ để xem: trang chưa cho đổi, vì các bộ viết chỉ đọc giá trị này lúc khởi động; một bản phát hành sau sẽ đọc lại ở mỗi lần gọi.", "raise": "Cho phép chữ dài hơn trước khi bị cắt; công cụ tìm kiếm có thể cắt bớt khi hiển thị.", "lower": "Chữ bị cắt ngắn hơn; ít chỗ cho điểm bán hàng.", "when": "Khi công cụ tìm kiếm đổi lượng chữ hiển thị, hoặc báo cáo tìm kiếm cho thấy chữ bị cắt hay quá mỏng.", "example": "Với mặc định 155 ký tự: dài hơn 155 sẽ bị cắt."}}},
{"key": "cis.seo.meta_min", "label": "Search description: shortest", "guide": {"en": {"what": "The shortest search description (meta description, the text under the title in search results) the checks and fitters accept, in characters. One band for every writer. Shown for reference only: the page refuses a change for now, because the writers read this value when they start; a later release reads it on every call.", "raise": "Short text is refused or lengthened more often.", "lower": "Shorter text is accepted; it may look thin in search results.", "when": "When search engines change how much they show, or search reports show the text cut or too thin.", "example": "With the default of 140 characters: anything shorter than 140 is refused or lengthened."}, "vi": {"what": "Độ dài ngắn nhất (ký tự) của mô tả tìm kiếm (meta description, dòng chữ dưới tiêu đề trong kết quả tìm kiếm) mà các bước kiểm và bước căn chỉnh chấp nhận. Một khoảng chung cho mọi bộ viết. Hiện chỉ để xem: trang chưa cho đổi, vì các bộ viết chỉ đọc giá trị này lúc khởi động; một bản phát hành sau sẽ đọc lại ở mỗi lần gọi.", "raise": "Chữ ngắn bị từ chối hoặc phải kéo dài thường xuyên hơn.", "lower": "Chữ ngắn hơn được chấp nhận; có thể trông sơ sài trong kết quả tìm kiếm.", "when": "Khi công cụ tìm kiếm đổi lượng chữ hiển thị, hoặc báo cáo tìm kiếm cho thấy chữ bị cắt hay quá mỏng.", "example": "Với mặc định 140 ký tự: ngắn hơn 140 bị từ chối hoặc phải kéo dài."}}},
{"key": "cis.seo.slug_max", "label": "Page address (slug): longest", "guide": {"en": {"what": "The longest page address part (slug), in characters; code cuts a longer one at a word boundary. One band for every writer. Shown for reference only: the page refuses a change for now, because the writers read this value when they start; a later release reads it on every call.", "raise": "Longer text is allowed before it is trimmed; search engines may cut it on screen.", "lower": "Text is trimmed shorter; less room for the selling point.", "when": "When search engines change how much they show, or search reports show the text cut or too thin.", "example": "With the default of 60 characters: anything longer than 60 is trimmed."}, "vi": {"what": "Độ dài tối đa (ký tự) của phần đường dẫn trang (slug); code cắt bớt tại ranh giới từ. Một khoảng chung cho mọi bộ viết. Hiện chỉ để xem: trang chưa cho đổi, vì các bộ viết chỉ đọc giá trị này lúc khởi động; một bản phát hành sau sẽ đọc lại ở mỗi lần gọi.", "raise": "Cho phép chữ dài hơn trước khi bị cắt; công cụ tìm kiếm có thể cắt bớt khi hiển thị.", "lower": "Chữ bị cắt ngắn hơn; ít chỗ cho điểm bán hàng.", "when": "Khi công cụ tìm kiếm đổi lượng chữ hiển thị, hoặc báo cáo tìm kiếm cho thấy chữ bị cắt hay quá mỏng.", "example": "Với mặc định 60 ký tự: dài hơn 60 sẽ bị cắt."}}},
{"key": "cis.seo.title_max", "label": "Search title: longest", "guide": {"en": {"what": "The longest search title the checks accept, in characters. One band for every writer. Shown for reference only: the page refuses a change for now, because the writers read this value when they start; a later release reads it on every call.", "raise": "Longer text is allowed before it is trimmed; search engines may cut it on screen.", "lower": "Text is trimmed shorter; less room for the selling point.", "when": "When search engines change how much they show, or search reports show the text cut or too thin.", "example": "With the default of 60 characters: anything longer than 60 is trimmed."}, "vi": {"what": "Độ dài tối đa (ký tự) của tiêu đề tìm kiếm mà các bước kiểm chấp nhận. Một khoảng chung cho mọi bộ viết. Hiện chỉ để xem: trang chưa cho đổi, vì các bộ viết chỉ đọc giá trị này lúc khởi động; một bản phát hành sau sẽ đọc lại ở mỗi lần gọi.", "raise": "Cho phép chữ dài hơn trước khi bị cắt; công cụ tìm kiếm có thể cắt bớt khi hiển thị.", "lower": "Chữ bị cắt ngắn hơn; ít chỗ cho điểm bán hàng.", "when": "Khi công cụ tìm kiếm đổi lượng chữ hiển thị, hoặc báo cáo tìm kiếm cho thấy chữ bị cắt hay quá mỏng.", "example": "Với mặc định 60 ký tự: dài hơn 60 sẽ bị cắt."}}},
{"key": "cis.seo.title_min", "label": "Search title: shortest", "guide": {"en": {"what": "The shortest search title (the clickable title in search results) the checks accept, in characters. One band for every writer. Shown for reference only: the page refuses a change for now, because the writers read this value when they start; a later release reads it on every call.", "raise": "Short text is refused or lengthened more often.", "lower": "Shorter text is accepted; it may look thin in search results.", "when": "When search engines change how much they show, or search reports show the text cut or too thin.", "example": "With the default of 45 characters: anything shorter than 45 is refused or lengthened."}, "vi": {"what": "Độ dài ngắn nhất (ký tự) của tiêu đề tìm kiếm (tiêu đề bấm được trong kết quả tìm kiếm) mà các bước kiểm chấp nhận. Một khoảng chung cho mọi bộ viết. Hiện chỉ để xem: trang chưa cho đổi, vì các bộ viết chỉ đọc giá trị này lúc khởi động; một bản phát hành sau sẽ đọc lại ở mỗi lần gọi.", "raise": "Chữ ngắn bị từ chối hoặc phải kéo dài thường xuyên hơn.", "lower": "Chữ ngắn hơn được chấp nhận; có thể trông sơ sài trong kết quả tìm kiếm.", "when": "Khi công cụ tìm kiếm đổi lượng chữ hiển thị, hoặc báo cáo tìm kiếm cho thấy chữ bị cắt hay quá mỏng.", "example": "Với mặc định 45 ký tự: ngắn hơn 45 bị từ chối hoặc phải kéo dài."}}},
{"key": "cis.settings.two_person_approval", "label": "Two-person approval of setting changes", "guide": {"en": {"what": "On: a change to a setting marked for two-person approval needs a second staff member to approve it. Off: the administrator may approve their own change with a reason, and a high-impact change e-mails the tech lead. While it is on, switching it off also needs a second person.", "raise": "On: every important change is checked by a second person; changes take longer.", "lower": "Off: one administrator can change settings alone; faster, with only the e-mail as a check.", "when": "Turn it on at the first production launch or the first paying tenant.", "example": "With the default off (development phase)."}, "vi": {"what": "Bật: thay đổi một cài đặt cần duyệt hai người phải được một nhân viên thứ hai duyệt. Tắt: quản trị viên được tự duyệt thay đổi của mình kèm lý do, và thay đổi có tác động lớn gửi e-mail cho trưởng nhóm kỹ thuật. Khi đang bật, muốn tắt cũng cần người thứ hai.", "raise": "Bật: mọi thay đổi quan trọng được người thứ hai kiểm tra; thay đổi chậm hơn.", "lower": "Tắt: một quản trị viên tự đổi được; nhanh hơn, chỉ có e-mail làm bước kiểm tra.", "when": "Bật khi ra mắt bản production đầu tiên hoặc có tenant trả phí đầu tiên.", "example": "Với mặc định tắt (off, giai đoạn phát triển)."}}},
{"key": "cis.spend.dfs_call_estimate_usd", "label": "Keyword data (DataForSEO): price estimate per call", "guide": {"en": {"what": "The price the system assumes for one DataForSEO call of each kind, before the real price is known, to check a run against its budget. Keep each price at or above what DataForSEO charges.", "raise": "Budget checks are more careful: runs stop earlier and never overspend.", "lower": "Runs are allowed further; if a price is below DataForSEO's, a run can pass its budget before the check sees it.", "when": "Change it when DataForSEO changes its prices, or when the spend report shows real prices above these.", "example": "With the default prices, for example $0.09 per search volume call and $0.002 per search results call."}, "vi": {"what": "Giá hệ thống giả định cho một lần gọi DataForSEO của từng loại, trước khi biết giá thật, để kiểm tra một lần chạy có vượt ngân sách không. Giữ mỗi giá bằng hoặc cao hơn giá DataForSEO tính.", "raise": "Kiểm tra ngân sách thận trọng hơn: lần chạy dừng sớm hơn và không bao giờ chi quá.", "lower": "Lần chạy được đi xa hơn; nếu giá thấp hơn giá DataForSEO, lần chạy có thể vượt ngân sách trước khi bước kiểm tra phát hiện.", "when": "Đổi khi DataForSEO đổi giá, hoặc khi báo cáo chi tiêu cho thấy giá thật cao hơn các giá này.", "example": "Với giá mặc định, ví dụ 0,09 USD mỗi lần gọi lấy lượng tìm kiếm và 0,002 USD mỗi lần gọi lấy kết quả tìm kiếm."}}},
{"key": "cis.spend.place_backfill_max_tours", "label": "Place backfill: tours per run", "guide": {"en": {"what": "How many tours one place backfill run (by country) may process. Each tour costs paid calls that locate its places and days, so this bounds the cost of one run.", "raise": "A country is filled in fewer runs; one run costs more and takes longer.", "lower": "Each run is smaller and cheaper; a large country needs more runs.", "when": "Change it when backfilling a large country takes too many runs (raise it), or after a run cost more than expected (lower it).", "example": "With the default of 50 tours per run."}, "vi": {"what": "Một lần chạy bổ sung địa điểm (theo nước) được xử lý tối đa bao nhiêu tour. Mỗi tour tốn các lần gọi trả phí để định vị địa điểm và ngày, nên số này chặn chi phí của một lần chạy.", "raise": "Một nước được bổ sung xong trong ít lần chạy hơn; mỗi lần tốn hơn và lâu hơn.", "lower": "Mỗi lần chạy nhỏ và rẻ hơn; nước lớn cần nhiều lần chạy hơn.", "when": "Đổi khi bổ sung một nước lớn mất quá nhiều lần chạy (nâng lên), hoặc sau một lần chạy tốn hơn dự kiến (hạ xuống).", "example": "Với mặc định 50 tour mỗi lần chạy."}}},
{"key": "cis.spend.question_topup_cap_usd", "label": "Question top-up: total keyword data spend", "guide": {"en": {"what": "The total DataForSEO spend of the admin question top-up (people-also-ask questions fetched from search results), across every run together. Each call is logged and counted against it.", "raise": "More question top-up runs can be made before it stops.", "lower": "The top-up stops sooner; topics get fewer new questions.", "when": "Change it when the top-up stops on the cap and topics still need questions (raise it).", "example": "With the default of $3 in total."}, "vi": {"what": "Tổng chi phí DataForSEO của chức năng bổ sung câu hỏi (các câu \"mọi người cũng hỏi\" lấy từ kết quả tìm kiếm) ở trang quản trị, cộng dồn mọi lần chạy. Mỗi lần gọi đều được ghi và trừ vào mức này.", "raise": "Chạy bổ sung câu hỏi được nhiều lần hơn trước khi dừng.", "lower": "Bổ sung dừng sớm hơn; chủ đề có ít câu hỏi mới hơn.", "when": "Đổi khi chức năng bổ sung dừng vì chạm trần mà chủ đề vẫn cần câu hỏi (nâng lên).", "example": "Với mặc định tổng cộng 3 USD."}}},
{"key": "cis.spend.rerun_wave_max_tours", "label": "Rerun wave: maximum tours", "guide": {"en": {"what": "The most tours one rerun wave may list. A wave rewrites its tours with paid calls, so this caps the size (and cost) of one wave. The rerun runbook still steps up: 3 tours, then up to 50, then a country.", "raise": "Bigger waves are allowed, for example a whole large country at once; one mistake reaches more tours.", "lower": "Waves must stay smaller; a large country is split into several waves.", "when": "Change it when a planned wave is refused for its size (raise it), or to keep waves small while a new writer version is being trialled (lower it).", "example": "With the default of 2,000 tours per wave."}, "vi": {"what": "Một đợt chạy lại (rerun wave) được liệt kê tối đa bao nhiêu tour. Mỗi đợt viết lại các tour bằng lần gọi trả phí, nên số này chặn quy mô (và chi phí) một đợt. Quy trình rerun vẫn đi từng bậc: 3 tour, rồi tới 50, rồi một nước.", "raise": "Cho phép đợt lớn hơn, ví dụ cả một nước lớn một lúc; một sai sót sẽ lan tới nhiều tour hơn.", "lower": "Đợt phải nhỏ hơn; một nước lớn phải chia thành nhiều đợt.", "when": "Đổi khi một đợt dự định bị từ chối vì quá lớn (nâng lên), hoặc để giữ đợt nhỏ trong lúc thử một phiên bản người viết mới (hạ xuống).", "example": "Với mặc định 2.000 tour mỗi đợt."}}},
{"key": "cis.spend.segment_research_max_usd_per_run", "label": "Segment research: keyword data spend per run", "guide": {"en": {"what": "The most one segment research run may spend on keyword data from DataForSEO. A run asking for more is refused, and a run without its own limit is capped here.", "raise": "One run can research more keywords and segments; a single run can cost more.", "lower": "Each run is cheaper and covers fewer keywords; large research needs several runs.", "when": "Change it when research runs stop on the cap before they cover the segments you need (raise it), or to keep keyword data spend low (lower it).", "example": "With the default of $50 per run."}, "vi": {"what": "Số tiền tối đa một lần nghiên cứu segment được chi cho dữ liệu từ khoá DataForSEO. Lần chạy xin nhiều hơn bị từ chối, lần chạy không tự đặt giới hạn thì bị chặn ở mức này.", "raise": "Một lần chạy nghiên cứu được nhiều từ khoá và segment hơn; một lần chạy có thể tốn hơn.", "lower": "Mỗi lần chạy rẻ hơn và phủ ít từ khoá hơn; nghiên cứu lớn cần chạy nhiều lần.", "when": "Đổi khi lần nghiên cứu dừng vì chạm trần trước khi phủ đủ segment cần (nâng lên), hoặc để giữ chi phí dữ liệu từ khoá thấp (hạ xuống).", "example": "Với mặc định 50 USD mỗi lần chạy."}}},
{"key": "cis.t2.version_repair_max", "label": "Agency tour rewrite: repair calls per version", "guide": {"en": {"what": "The paid repair calls that fix a flagged sentence or field one version of a tenant's tour may use. 0 = no repairs, the flags stay for staff.", "raise": "More flags are fixed automatically; the worst-case cost per version rises.", "lower": "Fewer automatic fixes: cheaper, more versions keep flags for staff.", "when": "Change it when versions often end with fixable flags left (raise it), or when repair spend grows without fewer flags (lower it).", "example": "With the default of 3 repair calls per version."}, "vi": {"what": "Số lần gọi sửa có trả phí (sửa một câu hoặc một trường bị gắn cờ) mà một phiên bản tour của tenant được dùng. 0 = không sửa, cờ để lại cho nhân viên.", "raise": "Nhiều cờ được sửa tự động hơn; chi phí xấu nhất mỗi phiên bản tăng.", "lower": "Ít lần sửa tự động hơn: rẻ hơn, nhiều phiên bản còn cờ cho nhân viên.", "when": "Đổi khi phiên bản thường kết thúc còn cờ sửa được (nâng lên), hoặc khi chi phí sửa tăng mà số cờ không giảm (hạ xuống).", "example": "Với mặc định 3 lần sửa mỗi phiên bản."}}},
{"key": "cis.t2.version_usd_max", "label": "Agency tour rewrite: spend cap per version", "guide": {"en": {"what": "The most the AI calls of one version of a tenant's tour may cost in all. Once the billed cost reaches it, no further call starts and the version keeps the best draft it has.", "raise": "Long or hard tours can finish all their writes and repairs; the worst case per version costs more.", "lower": "Spend per version is capped lower; long tours may stop before their repairs are done.", "when": "Change it when long tours often stop on the cap with flags left (raise it), or when a model price rises and the per-tour budget must hold (lower it).", "example": "With the default of $0.25 per tour version."}, "vi": {"what": "Tổng chi phí tối đa của các lần gọi AI cho một phiên bản tour của tenant. Khi chi phí thực tế chạm mức này, không lần gọi nào bắt đầu nữa và phiên bản giữ bản nháp tốt nhất đang có.", "raise": "Tour dài hoặc khó được chạy hết các lần viết và sửa; trường hợp xấu nhất mỗi phiên bản tốn hơn.", "lower": "Chi phí mỗi phiên bản bị chặn thấp hơn; tour dài có thể dừng trước khi sửa xong.", "when": "Đổi khi tour dài thường dừng vì chạm trần mà còn cờ lỗi (nâng lên), hoặc khi giá model tăng mà ngân sách mỗi tour phải giữ (hạ xuống).", "example": "Với mặc định 0,25 USD mỗi phiên bản tour."}}},
{"key": "cis.t2.version_voice_max", "label": "Agency tour rewrite: voice checks per version", "guide": {"en": {"what": "Calls that check whether a tenant's tour version sounds like the tenant's brand voice. The check only reports; it never changes the text. 0 = no voice report.", "raise": "2: if the job is retried, the voice check may run again (one more paid call). It never runs twice in one pass.", "lower": "0 saves the call; the tenant's voice report is empty.", "when": "Change it to 0 when nobody reads the voice report and cost matters; keep 1 while staff use it.", "example": "With the default of 1 voice check per version: one report, never repeated."}, "vi": {"what": "Số lần gọi kiểm tra phiên bản tour của tenant có đúng giọng thương hiệu của tenant không. Bước này chỉ báo cáo, không sửa chữ. 0 = không có báo cáo giọng văn.", "raise": "2: nếu job được chạy lại, bước kiểm tra giọng văn có thể chạy thêm một lần (thêm một lượt gọi có phí). Không bao giờ chạy hai lần trong một lượt.", "lower": "0 tiết kiệm lần gọi; báo cáo giọng văn của tenant để trống.", "when": "Đặt 0 khi không ai đọc báo cáo giọng văn và cần tiết kiệm; giữ 1 khi nhân viên còn dùng.", "example": "Với mặc định 1 lần kiểm tra giọng văn mỗi phiên bản: một báo cáo, không lặp lại."}}},
{"key": "cis.t2.version_writer_max", "label": "Agency tour rewrite: writer calls per version", "guide": {"en": {"what": "The paid writing calls (the first write and any rewrite of a field) one version of a tenant's tour may use, counted across job retries. When it is used up the version keeps the best draft it has.", "raise": "A version may be rewritten more often, which helps hard tours and raises the worst-case cost.", "lower": "Spend per version is lower and more predictable; more versions end with flags left for staff.", "when": "Change it when many tenant tours end with open flags that another write would fix (raise it), or when the spend per tenant tour is too high (lower it).", "example": "With the default of 2: the first write plus one more write per version."}, "vi": {"what": "Số lần gọi viết có trả phí (lần viết đầu và mỗi lần viết lại một trường) mà một phiên bản tour của tenant được dùng, tính gộp qua các lần job chạy lại. Dùng hết thì phiên bản giữ bản nháp tốt nhất đang có.", "raise": "Một phiên bản được viết lại nhiều lần hơn, giúp tour khó, nhưng chi phí xấu nhất tăng.", "lower": "Chi phí mỗi phiên bản thấp và dễ đoán hơn; nhiều phiên bản kết thúc còn cờ lỗi để nhân viên xử lý.", "when": "Đổi khi nhiều tour của tenant kết thúc còn cờ lỗi mà viết thêm một lần sẽ hết (nâng lên), hoặc khi chi phí mỗi tour của tenant quá cao (hạ xuống).", "example": "Với mặc định 2: lần viết đầu và thêm một lần viết mỗi phiên bản."}}},
{"key": "cis.t7.blog_chars_per_seed_word", "label": "Blog length per source word", "guide": {"en": {"what": "How many characters of finished blog the writer produces for each word of source material. The system divides the shortest blog it accepts (the setting 'Blog length: minimum (characters)', 4,700 by default) by this number to get the source words a topic needs before it is offered as a blog. Used only while the Blog minimum source words is on; 0 = not used.", "raise": "Each source word is expected to give more text, so a topic needs fewer source words: more topics are offered as blogs, and more of them come out too short and are held.", "lower": "Each source word is expected to give less text, so a topic needs more source words: fewer topics are offered as blogs, and the ones offered are more likely to reach the length.", "when": "Change it when the replay of stored blogs measures a different ratio, or when many blogs are held for being too short. A change needs that replay run as evidence.", "example": "With the default of 5.8 characters per word and the blog minimum of 4,700 characters: a topic needs 4,700 / 5.8 = about 811 source words for a blog. A replay of stored blogs on 13/11/2026 measured 3.364, which would ask for about 1,398 source words."}, "vi": {"what": "Mỗi từ tư liệu gốc cho ra bao nhiêu ký tự bài Blog hoàn chỉnh. Hệ thống lấy độ dài Blog ngắn nhất được chấp nhận (thiết lập 'Blog length: minimum (characters)', mặc định 4.700) chia cho số này để ra số từ nguồn một chủ đề cần có trước khi được đề xuất viết Blog. Chỉ dùng khi ngưỡng từ nguồn tối thiểu của Blog đang bật; 0 = không dùng.", "raise": "Mỗi từ nguồn được kỳ vọng cho ra nhiều chữ hơn, nên chủ đề cần ít từ nguồn hơn: nhiều chủ đề được đề xuất viết Blog hơn, và nhiều bài ra quá ngắn rồi bị giữ lại.", "lower": "Mỗi từ nguồn được kỳ vọng cho ra ít chữ hơn, nên chủ đề cần nhiều từ nguồn hơn: ít chủ đề được đề xuất viết Blog hơn, nhưng bài được đề xuất dễ đạt độ dài hơn.", "when": "Đổi khi lần chạy lại (replay) các bài Blog đã lưu đo ra tỉ lệ khác, hoặc khi nhiều bài Blog bị giữ vì quá ngắn. Mỗi lần đổi phải kèm lần replay đó làm bằng chứng.", "example": "Với mặc định 5,8 ký tự mỗi từ và mức blog tối thiểu 4.700 ký tự: chủ đề cần 4.700 / 5,8 = khoảng 811 từ nguồn để có bài Blog. Lần replay các bài đã lưu ngày 13/11/2026 đo được 3,364, tức là cần khoảng 1.398 từ nguồn."}}},
{"key": "cis.t7.blog_min_seed_words", "label": "Blog: minimum source words", "guide": {"en": {"what": "A topic is offered as a Blog article only when its source material (the facts and route notes the writer may use) has at least this many words; a thinner topic stays on the shorter channels. 0 switches the minimum off, and with it the length-based minimum (Blog length per source word).", "raise": "Fewer topics are offered as Blog articles, and the ones offered have more material, so fewer blogs are held for being too short. Raise it too far and good topics never get a blog.", "lower": "More topics get a blog, but a blog with thin material comes out short or repetitive and is held more often, and every held blog has already cost its writing calls.", "when": "Change it when many blogs are held for being too short (raise it), or when the slate offers almost no Blog topics although the tours have rich material (lower it).", "example": "With the default of 600 words: a topic with 600 source words or more may be offered as a blog, unless the length-based minimum asks for more."}, "vi": {"what": "Một chủ đề chỉ được đề xuất viết bài Blog khi tư liệu gốc (các dữ kiện và ghi chú lộ trình mà người viết được dùng) có ít nhất từng này từ; chủ đề mỏng hơn chỉ ở lại các kênh ngắn. 0 là tắt ngưỡng này, và tắt luôn ngưỡng tính theo độ dài (Độ dài Blog trên mỗi từ nguồn).", "raise": "Ít chủ đề được đề xuất viết Blog hơn, nhưng mỗi chủ đề có nhiều tư liệu hơn nên ít bài bị giữ lại vì quá ngắn. Nâng quá cao thì chủ đề tốt cũng không bao giờ có bài Blog.", "lower": "Nhiều chủ đề có bài Blog hơn, nhưng bài viết từ tư liệu mỏng sẽ ngắn hoặc lặp ý và bị giữ lại nhiều hơn; mỗi bài bị giữ đã tốn tiền gọi viết.", "when": "Đổi khi nhiều bài Blog bị giữ vì quá ngắn (nâng lên), hoặc khi danh sách đề xuất gần như không có chủ đề Blog dù tour có nhiều tư liệu (hạ xuống).", "example": "Với mặc định 600 từ: chủ đề có từ 600 từ nguồn trở lên được đề xuất viết Blog, trừ khi ngưỡng theo độ dài đòi nhiều hơn."}}},
{"key": "cis.t7.channel_bar_ads", "label": "Topic planning: bar for ads", "guide": {"en": {"what": "What a topic must have before it is proposed for ads. needs_demand = monthly searches for its keywords; needs_questions = real questions people ask about it; needs_said = how much the tour itineraries write about this moment, in characters of source text (all tours added together). Whole numbers; 0 = no bar. This channel is on demand, so it has no hub limit.", "raise": "Higher numbers (the stricter choice): fewer, stronger topics are proposed for this channel.", "lower": "Lower numbers (the looser choice): more topics qualify, including thinner ones.", "when": "Raise it when this channel gets topics nobody searches for or the source barely covers; lower it when the channel runs out of topics. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default: every number is 0: there is no bar, every topic may be proposed on demand."}, "vi": {"what": "Một chủ đề cần có những gì trước khi được đề xuất cho quảng cáo. needs_demand = lượt tìm kiếm mỗi tháng cho từ khoá của nó; needs_questions = số câu hỏi thật người dùng đặt ra; needs_said = lượng chữ các lịch trình tour viết về khoảnh khắc này, tính bằng số ký tự văn bản nguồn (cộng dồn mọi tour). Số nguyên; 0 = không có ngưỡng. Kênh này tạo theo yêu cầu nên không có giới hạn theo hub.", "raise": "Số cao hơn (lựa chọn chặt hơn): ít chủ đề hơn nhưng mạnh hơn được đề xuất cho kênh này.", "lower": "Số thấp hơn (lựa chọn nới hơn): nhiều chủ đề đủ điều kiện hơn, kể cả chủ đề mỏng.", "when": "Tăng khi kênh này nhận chủ đề không ai tìm hoặc nguồn hầu như không nói tới; giảm khi kênh hết chủ đề. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định: mọi số đều là 0: không có ngưỡng, chủ đề nào cũng có thể được đề xuất khi cần."}}},
{"key": "cis.t7.channel_bar_blog", "label": "Topic planning: bar for blog", "guide": {"en": {"what": "What a topic must have before it is proposed for blog. needs_demand = monthly searches for its keywords; needs_questions = real questions people ask about it; needs_said = how much the tour itineraries write about this moment, in characters of source text (all tours added together). Whole numbers; 0 on a needs_* number = no bar for it. most_per_hub = the most topics one hub (a place) may take on this channel; 99 = effectively off; 0 blocks every topic that belongs to a hub.", "raise": "Higher needs_* numbers or a lower most_per_hub (the stricter choice): fewer, stronger topics are proposed for this channel; a lower most_per_hub also spreads them over more places.", "lower": "Lower needs_* numbers or a higher most_per_hub (the looser choice): more topics qualify, including thinner ones, and one place may take more of them.", "when": "Raise it when this channel gets topics nobody searches for or the source barely covers; lower it when the channel runs out of topics. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default: a topic needs at least 1,000 monthly searches and 3 real questions people ask; the hub limit of 99 is effectively off."}, "vi": {"what": "Một chủ đề cần có những gì trước khi được đề xuất cho blog. needs_demand = lượt tìm kiếm mỗi tháng cho từ khoá của nó; needs_questions = số câu hỏi thật người dùng đặt ra; needs_said = lượng chữ các lịch trình tour viết về khoảnh khắc này, tính bằng số ký tự văn bản nguồn (cộng dồn mọi tour). Số nguyên; 0 ở một số needs_* = không có ngưỡng cho số đó. most_per_hub = số chủ đề tối đa một hub (một địa danh) được nhận trên kênh này; 99 = gần như không áp dụng; 0 chặn mọi chủ đề thuộc một hub.", "raise": "Số needs_* cao hơn hoặc most_per_hub thấp hơn (lựa chọn chặt hơn): ít chủ đề hơn nhưng mạnh hơn được đề xuất cho kênh này; most_per_hub thấp hơn còn rải chủ đề ra nhiều địa danh hơn.", "lower": "Số needs_* thấp hơn hoặc most_per_hub cao hơn (lựa chọn nới hơn): nhiều chủ đề đủ điều kiện hơn, kể cả chủ đề mỏng, và một địa danh có thể nhận nhiều chủ đề hơn.", "when": "Tăng khi kênh này nhận chủ đề không ai tìm hoặc nguồn hầu như không nói tới; giảm khi kênh hết chủ đề. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định: chủ đề cần ít nhất 1.000 lượt tìm mỗi tháng và 3 câu hỏi thật người dùng đặt ra; giới hạn 99 mỗi hub gần như không áp dụng."}}},
{"key": "cis.t7.channel_bar_email", "label": "Topic planning: bar for email", "guide": {"en": {"what": "What a topic must have before it is proposed for email. needs_demand = monthly searches for its keywords; needs_questions = real questions people ask about it; needs_said = how much the tour itineraries write about this moment, in characters of source text (all tours added together). Whole numbers; 0 = no bar. This channel is on demand, so it has no hub limit.", "raise": "Higher numbers (the stricter choice): fewer, stronger topics are proposed for this channel.", "lower": "Lower numbers (the looser choice): more topics qualify, including thinner ones.", "when": "Raise it when this channel gets topics nobody searches for or the source barely covers; lower it when the channel runs out of topics. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default: every number is 0: there is no bar, every topic may be proposed on demand."}, "vi": {"what": "Một chủ đề cần có những gì trước khi được đề xuất cho email. needs_demand = lượt tìm kiếm mỗi tháng cho từ khoá của nó; needs_questions = số câu hỏi thật người dùng đặt ra; needs_said = lượng chữ các lịch trình tour viết về khoảnh khắc này, tính bằng số ký tự văn bản nguồn (cộng dồn mọi tour). Số nguyên; 0 = không có ngưỡng. Kênh này tạo theo yêu cầu nên không có giới hạn theo hub.", "raise": "Số cao hơn (lựa chọn chặt hơn): ít chủ đề hơn nhưng mạnh hơn được đề xuất cho kênh này.", "lower": "Số thấp hơn (lựa chọn nới hơn): nhiều chủ đề đủ điều kiện hơn, kể cả chủ đề mỏng.", "when": "Tăng khi kênh này nhận chủ đề không ai tìm hoặc nguồn hầu như không nói tới; giảm khi kênh hết chủ đề. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định: mọi số đều là 0: không có ngưỡng, chủ đề nào cũng có thể được đề xuất khi cần."}}},
{"key": "cis.t7.channel_bar_facebook", "label": "Topic planning: bar for Facebook", "guide": {"en": {"what": "What a topic must have before it is proposed for Facebook. needs_demand = monthly searches for its keywords; needs_questions = real questions people ask about it; needs_said = how much the tour itineraries write about this moment, in characters of source text (all tours added together). Whole numbers; 0 on a needs_* number = no bar for it. most_per_hub = the most topics one hub (a place) may take on this channel; 99 = effectively off; 0 blocks every topic that belongs to a hub.", "raise": "Higher needs_* numbers or a lower most_per_hub (the stricter choice): fewer, stronger topics are proposed for this channel; a lower most_per_hub also spreads them over more places.", "lower": "Lower needs_* numbers or a higher most_per_hub (the looser choice): more topics qualify, including thinner ones, and one place may take more of them.", "when": "Raise it when this channel gets topics nobody searches for or the source barely covers; lower it when the channel runs out of topics. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default: a topic needs at least 150 characters of itinerary text about the moment (all tours added together); the hub limit of 99 is effectively off."}, "vi": {"what": "Một chủ đề cần có những gì trước khi được đề xuất cho Facebook. needs_demand = lượt tìm kiếm mỗi tháng cho từ khoá của nó; needs_questions = số câu hỏi thật người dùng đặt ra; needs_said = lượng chữ các lịch trình tour viết về khoảnh khắc này, tính bằng số ký tự văn bản nguồn (cộng dồn mọi tour). Số nguyên; 0 ở một số needs_* = không có ngưỡng cho số đó. most_per_hub = số chủ đề tối đa một hub (một địa danh) được nhận trên kênh này; 99 = gần như không áp dụng; 0 chặn mọi chủ đề thuộc một hub.", "raise": "Số needs_* cao hơn hoặc most_per_hub thấp hơn (lựa chọn chặt hơn): ít chủ đề hơn nhưng mạnh hơn được đề xuất cho kênh này; most_per_hub thấp hơn còn rải chủ đề ra nhiều địa danh hơn.", "lower": "Số needs_* thấp hơn hoặc most_per_hub cao hơn (lựa chọn nới hơn): nhiều chủ đề đủ điều kiện hơn, kể cả chủ đề mỏng, và một địa danh có thể nhận nhiều chủ đề hơn.", "when": "Tăng khi kênh này nhận chủ đề không ai tìm hoặc nguồn hầu như không nói tới; giảm khi kênh hết chủ đề. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định: chủ đề cần ít nhất 150 ký tự mô tả trong lịch trình (cộng dồn mọi tour); giới hạn 99 mỗi hub gần như không áp dụng."}}},
{"key": "cis.t7.channel_bar_instagram", "label": "Topic planning: bar for Instagram", "guide": {"en": {"what": "What a topic must have before it is proposed for Instagram. needs_demand = monthly searches for its keywords; needs_questions = real questions people ask about it; needs_said = how much the tour itineraries write about this moment, in characters of source text (all tours added together). Whole numbers; 0 on a needs_* number = no bar for it. most_per_hub = the most topics one hub (a place) may take on this channel; 99 = effectively off; 0 blocks every topic that belongs to a hub.", "raise": "Higher needs_* numbers or a lower most_per_hub (the stricter choice): fewer, stronger topics are proposed for this channel; a lower most_per_hub also spreads them over more places.", "lower": "Lower needs_* numbers or a higher most_per_hub (the looser choice): more topics qualify, including thinner ones, and one place may take more of them.", "when": "Raise it when this channel gets topics nobody searches for or the source barely covers; lower it when the channel runs out of topics. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default: a topic needs at least 150 characters of itinerary text about the moment (all tours added together); the hub limit of 99 is effectively off."}, "vi": {"what": "Một chủ đề cần có những gì trước khi được đề xuất cho Instagram. needs_demand = lượt tìm kiếm mỗi tháng cho từ khoá của nó; needs_questions = số câu hỏi thật người dùng đặt ra; needs_said = lượng chữ các lịch trình tour viết về khoảnh khắc này, tính bằng số ký tự văn bản nguồn (cộng dồn mọi tour). Số nguyên; 0 ở một số needs_* = không có ngưỡng cho số đó. most_per_hub = số chủ đề tối đa một hub (một địa danh) được nhận trên kênh này; 99 = gần như không áp dụng; 0 chặn mọi chủ đề thuộc một hub.", "raise": "Số needs_* cao hơn hoặc most_per_hub thấp hơn (lựa chọn chặt hơn): ít chủ đề hơn nhưng mạnh hơn được đề xuất cho kênh này; most_per_hub thấp hơn còn rải chủ đề ra nhiều địa danh hơn.", "lower": "Số needs_* thấp hơn hoặc most_per_hub cao hơn (lựa chọn nới hơn): nhiều chủ đề đủ điều kiện hơn, kể cả chủ đề mỏng, và một địa danh có thể nhận nhiều chủ đề hơn.", "when": "Tăng khi kênh này nhận chủ đề không ai tìm hoặc nguồn hầu như không nói tới; giảm khi kênh hết chủ đề. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định: chủ đề cần ít nhất 150 ký tự mô tả trong lịch trình (cộng dồn mọi tour); giới hạn 99 mỗi hub gần như không áp dụng."}}},
{"key": "cis.t7.channel_bar_landing_page", "label": "Topic planning: bar for landing page", "guide": {"en": {"what": "What a topic must have before it is proposed for landing page. needs_demand = monthly searches for its keywords; needs_questions = real questions people ask about it; needs_said = how much the tour itineraries write about this moment, in characters of source text (all tours added together). Whole numbers; 0 = no bar. This channel is on demand, so it has no hub limit.", "raise": "Higher numbers (the stricter choice): fewer, stronger topics are proposed for this channel.", "lower": "Lower numbers (the looser choice): more topics qualify, including thinner ones.", "when": "Raise it when this channel gets topics nobody searches for or the source barely covers; lower it when the channel runs out of topics. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default: every number is 0: there is no bar, every topic may be proposed on demand."}, "vi": {"what": "Một chủ đề cần có những gì trước khi được đề xuất cho landing page. needs_demand = lượt tìm kiếm mỗi tháng cho từ khoá của nó; needs_questions = số câu hỏi thật người dùng đặt ra; needs_said = lượng chữ các lịch trình tour viết về khoảnh khắc này, tính bằng số ký tự văn bản nguồn (cộng dồn mọi tour). Số nguyên; 0 = không có ngưỡng. Kênh này tạo theo yêu cầu nên không có giới hạn theo hub.", "raise": "Số cao hơn (lựa chọn chặt hơn): ít chủ đề hơn nhưng mạnh hơn được đề xuất cho kênh này.", "lower": "Số thấp hơn (lựa chọn nới hơn): nhiều chủ đề đủ điều kiện hơn, kể cả chủ đề mỏng.", "when": "Tăng khi kênh này nhận chủ đề không ai tìm hoặc nguồn hầu như không nói tới; giảm khi kênh hết chủ đề. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định: mọi số đều là 0: không có ngưỡng, chủ đề nào cũng có thể được đề xuất khi cần."}}},
{"key": "cis.t7.channel_bar_linkedin", "label": "Topic planning: bar for LinkedIn", "guide": {"en": {"what": "What a topic must have before it is proposed for LinkedIn. needs_demand = monthly searches for its keywords; needs_questions = real questions people ask about it; needs_said = how much the tour itineraries write about this moment, in characters of source text (all tours added together). Whole numbers; 0 on a needs_* number = no bar for it. most_per_hub = the most topics one hub (a place) may take on this channel; 99 = effectively off; 0 blocks every topic that belongs to a hub.", "raise": "Higher needs_* numbers or a lower most_per_hub (the stricter choice): fewer, stronger topics are proposed for this channel; a lower most_per_hub also spreads them over more places.", "lower": "Lower needs_* numbers or a higher most_per_hub (the looser choice): more topics qualify, including thinner ones, and one place may take more of them.", "when": "Raise it when this channel gets topics nobody searches for or the source barely covers; lower it when the channel runs out of topics. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default: a topic needs at least 150 characters of itinerary text about the moment (all tours added together); the hub limit of 99 is effectively off."}, "vi": {"what": "Một chủ đề cần có những gì trước khi được đề xuất cho LinkedIn. needs_demand = lượt tìm kiếm mỗi tháng cho từ khoá của nó; needs_questions = số câu hỏi thật người dùng đặt ra; needs_said = lượng chữ các lịch trình tour viết về khoảnh khắc này, tính bằng số ký tự văn bản nguồn (cộng dồn mọi tour). Số nguyên; 0 ở một số needs_* = không có ngưỡng cho số đó. most_per_hub = số chủ đề tối đa một hub (một địa danh) được nhận trên kênh này; 99 = gần như không áp dụng; 0 chặn mọi chủ đề thuộc một hub.", "raise": "Số needs_* cao hơn hoặc most_per_hub thấp hơn (lựa chọn chặt hơn): ít chủ đề hơn nhưng mạnh hơn được đề xuất cho kênh này; most_per_hub thấp hơn còn rải chủ đề ra nhiều địa danh hơn.", "lower": "Số needs_* thấp hơn hoặc most_per_hub cao hơn (lựa chọn nới hơn): nhiều chủ đề đủ điều kiện hơn, kể cả chủ đề mỏng, và một địa danh có thể nhận nhiều chủ đề hơn.", "when": "Tăng khi kênh này nhận chủ đề không ai tìm hoặc nguồn hầu như không nói tới; giảm khi kênh hết chủ đề. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định: chủ đề cần ít nhất 150 ký tự mô tả trong lịch trình (cộng dồn mọi tour); giới hạn 99 mỗi hub gần như không áp dụng."}}},
{"key": "cis.t7.channel_bar_tiktok", "label": "Topic planning: bar for TikTok", "guide": {"en": {"what": "What a topic must have before it is proposed for TikTok. needs_demand = monthly searches for its keywords; needs_questions = real questions people ask about it; needs_said = how much the tour itineraries write about this moment, in characters of source text (all tours added together). Whole numbers; 0 on a needs_* number = no bar for it. most_per_hub = the most topics one hub (a place) may take on this channel; 99 = effectively off; 0 blocks every topic that belongs to a hub.", "raise": "Higher needs_* numbers or a lower most_per_hub (the stricter choice): fewer, stronger topics are proposed for this channel; a lower most_per_hub also spreads them over more places.", "lower": "Lower needs_* numbers or a higher most_per_hub (the looser choice): more topics qualify, including thinner ones, and one place may take more of them.", "when": "Raise it when this channel gets topics nobody searches for or the source barely covers; lower it when the channel runs out of topics. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default: a topic needs at least 150 characters of itinerary text about the moment (all tours added together); the hub limit of 99 is effectively off."}, "vi": {"what": "Một chủ đề cần có những gì trước khi được đề xuất cho TikTok. needs_demand = lượt tìm kiếm mỗi tháng cho từ khoá của nó; needs_questions = số câu hỏi thật người dùng đặt ra; needs_said = lượng chữ các lịch trình tour viết về khoảnh khắc này, tính bằng số ký tự văn bản nguồn (cộng dồn mọi tour). Số nguyên; 0 ở một số needs_* = không có ngưỡng cho số đó. most_per_hub = số chủ đề tối đa một hub (một địa danh) được nhận trên kênh này; 99 = gần như không áp dụng; 0 chặn mọi chủ đề thuộc một hub.", "raise": "Số needs_* cao hơn hoặc most_per_hub thấp hơn (lựa chọn chặt hơn): ít chủ đề hơn nhưng mạnh hơn được đề xuất cho kênh này; most_per_hub thấp hơn còn rải chủ đề ra nhiều địa danh hơn.", "lower": "Số needs_* thấp hơn hoặc most_per_hub cao hơn (lựa chọn nới hơn): nhiều chủ đề đủ điều kiện hơn, kể cả chủ đề mỏng, và một địa danh có thể nhận nhiều chủ đề hơn.", "when": "Tăng khi kênh này nhận chủ đề không ai tìm hoặc nguồn hầu như không nói tới; giảm khi kênh hết chủ đề. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định: chủ đề cần ít nhất 150 ký tự mô tả trong lịch trình (cộng dồn mọi tour); giới hạn 99 mỗi hub gần như không áp dụng."}}},
{"key": "cis.t7.debate_contested_cut", "label": "Topic planning: contested threshold", "guide": {"en": {"what": "How contested a topic's keyword may be (0 = nobody competes, 1 = fully contested) before the topic is flagged as contested. What a flag does is set by 'Topic planning: what to do with contested topics'.", "raise": "Fewer topics are flagged; harder keywords stay in the main list.", "lower": "More topics are flagged and, in cut mode, dropped.", "when": "Lower it when tenants get topics they cannot rank for; raise it when good topics are flagged. In the first country measured no topic went above 0.33. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default of 0.5: a keyword scored 0.6 is flagged, 0.3 is not."}, "vi": {"what": "Từ khoá của một chủ đề được cạnh tranh tới mức nào (0 = không ai cạnh tranh, 1 = cạnh tranh hoàn toàn) trước khi chủ đề bị gắn cờ cạnh tranh. Cờ đó dẫn tới gì do thiết lập 'Lập chủ đề: xử lý chủ đề cạnh tranh' quyết định.", "raise": "Ít chủ đề bị gắn cờ hơn; từ khoá khó hơn vẫn ở danh sách chính.", "lower": "Nhiều chủ đề bị gắn cờ hơn và, ở chế độ cut, bị loại.", "when": "Giảm khi đại lý nhận chủ đề khó lên thứ hạng; tăng khi chủ đề tốt bị gắn cờ. Ở nước đầu tiên được đo, không chủ đề nào vượt 0,33. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định 0,5: từ khoá được 0,6 bị gắn cờ, 0,3 thì không."}}},
{"key": "cis.t7.debate_max_cut_fraction", "label": "Topic planning: most of a list that may be cut", "guide": {"en": {"what": "In cut mode, the largest share of one channel's topic list that may be dropped in one planning run, so a channel never loses all its topics at once.", "raise": "More flagged topics may be dropped in one run.", "lower": "Fewer topics are dropped; more contested ones stay, at the end of the list.", "when": "Only matters in cut mode: lower it if a channel's list gets too short after a run. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default of 0.5: at most half of a channel's list is cut in one run."}, "vi": {"what": "Ở chế độ cut, tỷ lệ lớn nhất của danh sách chủ đề một kênh có thể bị loại trong một lần lập chủ đề, để kênh không bao giờ mất hết chủ đề một lúc.", "raise": "Nhiều chủ đề bị gắn cờ có thể bị loại hơn trong một lần chạy.", "lower": "Ít chủ đề bị loại hơn; nhiều chủ đề cạnh tranh vẫn ở lại, cuối danh sách.", "when": "Chỉ có tác dụng ở chế độ cut: giảm nếu danh sách của kênh còn quá ngắn sau một lần chạy. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định 0,5: mỗi lần chạy loại tối đa một nửa danh sách của kênh."}}},
{"key": "cis.t9.blog_chars_max", "label": "Blog length: maximum (characters)", "guide": {"en": {"what": "The longest blog accepted, in characters of plain text (tags not counted). A longer blog is shortened or held. It must stay above the minimum.", "raise": "Longer blogs pass as written.", "lower": "More long blogs are shortened (paid) or held.", "when": "When tenants find blogs too long to use, or long blogs are cut for no reason. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default of 13,000 characters (about 2,240 words): a 14,000-character blog is too long."}, "vi": {"what": "Blog dài nhất được chấp nhận, tính bằng ký tự văn bản thuần (không tính thẻ). Blog dài hơn phải rút ngắn hoặc bị giữ. Phải luôn cao hơn mức tối thiểu.", "raise": "Blog dài hơn được giữ nguyên.", "lower": "Nhiều blog dài phải rút ngắn (có phí) hoặc bị giữ hơn.", "when": "Khi đại lý thấy blog quá dài để dùng, hoặc blog dài bị cắt không cần thiết. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định 13.000 ký tự (khoảng 2.240 từ): blog 14.000 ký tự là quá dài."}}},
{"key": "cis.t9.blog_chars_min", "label": "Blog length: minimum (characters)", "guide": {"en": {"what": "The shortest blog accepted, in characters of plain text (tags not counted). A shorter blog is lengthened or held. The writer aims above it by the length margin, and topic planning sizes the source a blog needs from it.", "raise": "Longer blogs are required: more are lengthened (paid) or held, and topics need more source material.", "lower": "Shorter blogs pass; they may read thin.", "when": "Change it with the content strategy, for example when search reports favour longer or shorter articles. Change the length margin and the ceiling with it. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default of 4,700 characters (about 810 words): a 4,500-character blog is too short."}, "vi": {"what": "Blog ngắn nhất được chấp nhận, tính bằng ký tự văn bản thuần (không tính thẻ). Blog ngắn hơn phải kéo dài hoặc bị giữ. Bộ viết nhắm cao hơn mức này theo tỷ lệ dư, và bước lập chủ đề dựa vào nó để tính lượng nguồn một blog cần.", "raise": "Đòi blog dài hơn: nhiều bài phải kéo dài (có phí) hoặc bị giữ hơn, và chủ đề cần nhiều tư liệu nguồn hơn.", "lower": "Blog ngắn hơn được chấp nhận; có thể đọc sơ sài.", "when": "Đổi theo chiến lược nội dung, ví dụ khi báo cáo tìm kiếm ưu tiên bài dài hay ngắn hơn. Đổi cùng tỷ lệ dư và mức trần. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định 4.700 ký tự (khoảng 810 từ): blog 4.500 ký tự là quá ngắn."}}},
{"key": "cis.t9.max_attempts", "label": "Write attempts per article", "guide": {"en": {"what": "How many steps the article writer takes on one piece before it stops: 1 = the first draft, 2 = one repair of the problems the checks found, 3 = a third step (in the default mode a free label of what is still wrong; in the older mode one more paid sentence repair).", "raise": "3 gives a piece one more chance before it is held; in the older mode that chance is a paid call.", "lower": "2 stops after one repair: no third step. In the default mode it costs the same as 3, in the older mode it saves one paid call per piece and more pieces are held for staff.", "when": "Change it when the cost per article matters more than the share of articles held (set 2), or the other way round (set 3).", "example": "With the default of 3: write, repair once, then the third step."}, "vi": {"what": "Người viết bài thực hiện bao nhiêu bước trên một bài trước khi dừng: 1 = bản nháp đầu, 2 = một lần sửa các lỗi mà bước kiểm tra tìm ra, 3 = bước thứ ba (ở chế độ mặc định là gắn nhãn miễn phí những gì còn sai; ở chế độ cũ là thêm một lần sửa câu có trả phí).", "raise": "3 cho bài thêm một cơ hội trước khi bị giữ lại; ở chế độ cũ cơ hội đó là một lần gọi trả phí.", "lower": "2 dừng sau một lần sửa, không có bước thứ ba. Ở chế độ mặc định chi phí như 3; ở chế độ cũ tiết kiệm một lần gọi trả phí mỗi bài và nhiều bài bị giữ lại chờ nhân viên hơn.", "when": "Đổi khi chi phí mỗi bài quan trọng hơn tỉ lệ bài bị giữ (đặt 2), hoặc ngược lại (đặt 3).", "example": "Với mặc định 3: viết, sửa một lần, rồi đến bước thứ ba."}}},
{"key": "cis.t9.repeat_drop_near_exact", "label": "Blog repeat cleanup: how alike two sentences must be", "guide": {"en": {"what": "After a blog is repaired, a free cleanup step deletes the later copy of a sentence that repeats an earlier one, so the whole article is not held for one repeated sentence. This is how alike the two sentences must be, word for word in order (1.0 = exactly the same). The cleanup never takes a blog under its minimum length.", "raise": "Only exact or almost exact copies are deleted; more blogs keep a repeated sentence and are held by the repeat check for staff.", "lower": "Sentences that only say something similar are deleted too; fewer holds, but the cleanup may remove a sentence a reader would have wanted.", "when": "Change it when the repeat check still holds many blogs for a sentence told twice (lower it a little), or when readers or reviewers find sentences missing (raise it). A change needs a replay run as evidence.", "example": "With the default of 0.9: the later sentence is deleted when 90 % of its words match the earlier one in the same order."}, "vi": {"what": "Sau khi bài Blog được sửa, một bước dọn miễn phí xoá bản sau của câu lặp lại câu trước đó, để cả bài không bị giữ lại chỉ vì một câu lặp. Đây là mức giống nhau của hai câu, so từng từ theo đúng thứ tự (1,0 = giống hệt). Bước dọn không bao giờ làm bài Blog ngắn hơn độ dài tối thiểu.", "raise": "Chỉ xoá những câu giống hệt hoặc gần như giống hệt; nhiều bài vẫn còn câu lặp và bị bước kiểm tra lặp giữ lại chờ nhân viên.", "lower": "Cả những câu chỉ na ná nhau cũng bị xoá; ít bài bị giữ hơn, nhưng có thể mất một câu người đọc cần.", "when": "Đổi khi bước kiểm tra lặp vẫn giữ lại nhiều bài vì một câu nói hai lần (hạ xuống một chút), hoặc khi người duyệt thấy bài bị mất câu (nâng lên). Mỗi lần đổi phải kèm lần replay làm bằng chứng.", "example": "Với mặc định 0,9: câu sau bị xoá khi 90 % số từ khớp với câu trước theo đúng thứ tự."}}},
{"key": "cis.writing_memory.month_cap_usd", "label": "Writing memory: monthly AI spend cap", "guide": {"en": {"what": "The most the writing-memory learning loop (mining past edits, its evaluation and shadow runs) may spend on AI calls in one calendar month (UTC). A run whose estimate would pass the cap is refused before any call.", "raise": "The learning loop can run more or larger batches each month; AI spend rises.", "lower": "Fewer learning runs fit in the month; the loop learns more slowly. 0 stops it.", "when": "Change it when learning runs are refused for the cap while you still want them (raise it), or when the monthly AI bill must come down (lower it).", "example": "With the default of $25 per month."}, "vi": {"what": "Số tiền tối đa vòng học của writing memory (khai thác các lần sửa trước, đánh giá và chạy thử song song) được chi cho AI trong một tháng dương lịch (giờ UTC). Lần chạy có ước tính vượt trần bị từ chối trước khi gọi.", "raise": "Vòng học chạy được nhiều lô hơn hoặc lô lớn hơn mỗi tháng; chi phí AI tăng.", "lower": "Ít lần học vừa trong tháng hơn; vòng học tiến chậm hơn. 0 là dừng hẳn.", "when": "Đổi khi các lần học bị từ chối vì chạm trần mà bạn vẫn muốn chạy (nâng lên), hoặc khi hoá đơn AI hằng tháng phải giảm (hạ xuống).", "example": "Với mặc định 25 USD mỗi tháng."}}},
{"key": "tripplanner.ai.narration_cache_ttl_hours", "label": "AI trip story: hours a story is reused", "guide": {"en": {"what": "How long a written trip story is reused for the same itinerary before a new one is written. A reused story costs nothing. If TripPlanner cannot read the settings, it falls back to its own server value, then this default.", "raise": "Fewer paid stories; a traveller may see an older story after the itinerary text was improved.", "lower": "Stories are rewritten more often: fresher wording, more paid calls.", "when": "Lower it right after the trip text or the story prompt changes, so travellers see the new version sooner; raise it to cut cost.", "example": "With the default of 168 hours (7 days): the same itinerary gets the same story for a week."}, "vi": {"what": "Một câu chuyện chuyến đi đã viết được dùng lại cho cùng lịch trình trong bao lâu trước khi viết câu chuyện mới. Dùng lại thì không tốn phí. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị cấu hình riêng trên máy chủ, rồi tới giá trị mặc định này.", "raise": "Ít câu chuyện có phí hơn; khách có thể thấy câu chuyện cũ sau khi nội dung lịch trình đã được cải thiện.", "lower": "Câu chuyện được viết lại thường hơn: lời văn mới hơn, nhiều lượt gọi có phí hơn.", "when": "Giảm ngay sau khi nội dung chuyến đi hay prompt kể chuyện thay đổi, để khách sớm thấy bản mới; tăng để giảm chi phí.", "example": "Với mặc định 168 giờ (7 ngày): cùng một lịch trình nhận cùng một câu chuyện trong một tuần."}}},
{"key": "tripplanner.ai.narration_max_tokens", "label": "AI trip story: longest answer (tokens)", "guide": {"en": {"what": "The longest answer one trip story call may write, in tokens (a token is about three quarters of a word). A reasoning model may need more and is given its own minimum, never less.", "raise": "Long trips get a complete story; each call can cost a little more.", "lower": "Cheaper calls; a long trip's story may be cut short and the planner falls back to the basic story.", "when": "Raise it when long trips show the basic story instead of the AI one; lower it only if stories run long.", "example": "With the default of 1200 tokens: about 900 words, enough for a two-week trip."}, "vi": {"what": "Câu trả lời dài nhất một lượt kể chuyện chuyến đi được viết, tính bằng token (một token khoảng ba phần tư từ). Model suy luận có thể cần nhiều hơn và có mức tối thiểu riêng, không bao giờ thấp hơn.", "raise": "Chuyến dài nhận câu chuyện trọn vẹn; mỗi lượt gọi có thể tốn hơn chút.", "lower": "Lượt gọi rẻ hơn; câu chuyện của chuyến dài có thể bị cắt và planner dùng câu chuyện cơ bản thay thế.", "when": "Tăng khi chuyến dài hiện câu chuyện cơ bản thay vì bản AI; chỉ giảm nếu câu chuyện quá dài.", "example": "Với mặc định 1200 token: khoảng 900 từ, đủ cho chuyến đi hai tuần."}}},
{"key": "tripplanner.ai.plan_chat_max_steps", "label": "Planning chat: model calls per message", "guide": {"en": {"what": "How many model calls one planning chat message may use: look-up steps (search, places) plus the final answer. Each step is a paid call; the last one must answer.", "raise": "The chat can look up more before answering: better answers to complex requests, more cost per message.", "lower": "Cheaper, faster messages; complex requests get a shallower answer.", "when": "Raise it when answers miss information the chat could have looked up; lower it to cut cost per message.", "example": "With the default of 3: up to two look-ups and the answer."}, "vi": {"what": "Một tin nhắn trò chuyện lập kế hoạch được dùng bao nhiêu lượt gọi model: các bước tra cứu (tìm kiếm, địa điểm) cộng câu trả lời cuối. Mỗi bước là một lượt gọi có phí; lượt cuối phải trả lời.", "raise": "Trò chuyện tra cứu được nhiều hơn trước khi trả lời: trả lời tốt hơn cho yêu cầu phức tạp, tốn hơn mỗi tin nhắn.", "lower": "Tin nhắn rẻ hơn, nhanh hơn; yêu cầu phức tạp nhận câu trả lời nông hơn.", "when": "Tăng khi câu trả lời thiếu thông tin lẽ ra tra được; giảm để bớt chi phí mỗi tin nhắn.", "example": "Với mặc định 3: tối đa hai lần tra cứu và câu trả lời."}}},
{"key": "tripplanner.ai.plan_chat_max_tokens", "label": "Planning chat: longest answer per call (tokens)", "guide": {"en": {"what": "The longest answer one planning chat model call may write, in tokens (about three quarters of a word each). A reasoning model may be given more, never less.", "raise": "Longer, fuller chat answers; each call can cost more.", "lower": "Shorter, cheaper answers; a detailed answer may be cut.", "when": "Raise it when chat answers stop mid-sentence; lower it when they ramble.", "example": "With the default of 700 tokens: about 500 words per answer."}, "vi": {"what": "Câu trả lời dài nhất một lượt gọi model của trò chuyện lập kế hoạch được viết, tính bằng token (khoảng ba phần tư từ mỗi token). Model suy luận có thể được nhiều hơn, không bao giờ ít hơn.", "raise": "Câu trả lời dài và đầy đủ hơn; mỗi lượt gọi có thể tốn hơn.", "lower": "Câu trả lời ngắn và rẻ hơn; câu trả lời chi tiết có thể bị cắt.", "when": "Tăng khi câu trả lời dừng giữa câu; giảm khi câu trả lời lan man.", "example": "Với mặc định 700 token: khoảng 500 từ mỗi câu trả lời."}}},
{"key": "tripplanner.handoff.advisor_demo", "label": "Send to advisor on the AA planner is a demo", "guide": {"en": {"what": "On (business-to-business only): on the bare planner and the AA demo, 'send to advisor' answers that the service is for agencies and stores nothing (no registration, no enquiry, no Booking case). An agency's planner sends leads to that agency either way. Off turns the old AA hand-off back on. If TripPlanner cannot read the settings, it falls back to its own server value, then this default.", "raise": "On: the AA planner never collects traveller contacts; agencies are unaffected.", "lower": "Off: the AA planner collects traveller contacts and creates enquiries and Booking cases again.", "when": "Keep it on while AA sells only to agencies; turn it off only if AA decides to take travellers directly again.", "example": "With the default on: a traveller on the AA demo who presses 'send to advisor' sees the agencies-only message."}, "vi": {"what": "Bật (chỉ phục vụ doanh nghiệp): trên planner trần và bản demo của AA, 'gửi cho tư vấn viên' trả lời rằng dịch vụ dành cho đại lý và không lưu gì (không đăng ký, không yêu cầu, không tạo hồ sơ Booking). Planner của đại lý vẫn gửi lead cho đại lý đó trong cả hai trường hợp. Tắt sẽ bật lại luồng chuyển khách cũ của AA. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị cấu hình riêng trên máy chủ, rồi tới giá trị mặc định này.", "raise": "Bật: planner của AA không bao giờ thu thông tin liên hệ của khách; đại lý không bị ảnh hưởng.", "lower": "Tắt: planner của AA lại thu thông tin liên hệ của khách, tạo yêu cầu và hồ sơ Booking.", "when": "Giữ bật khi AA chỉ bán cho đại lý; chỉ tắt nếu AA quyết định nhận khách trực tiếp trở lại.", "example": "Với mặc định on: khách trên bản demo của AA bấm 'gửi cho tư vấn viên' sẽ thấy thông báo chỉ dành cho đại lý."}}},
{"key": "tripplanner.handoff.require_registration", "label": "Old AA hand-off: registration first", "guide": {"en": {"what": "On: the old AA hand-off (used only when 'Send to advisor on the AA planner is a demo' is off) asks for the traveller's name and a phone or e-mail before sending. If TripPlanner cannot read the settings, it falls back to its own server value, then this default.", "raise": "On: every hand-off carries contact details the team can follow up.", "lower": "Off: travellers can send without details; more hand-offs, many without a way to reply.", "when": "Matters only with the demo switch off; turn it off only to test the flow.", "example": "With the default on: a traveller must enter a name and a phone or e-mail first."}, "vi": {"what": "Bật: luồng chuyển khách cũ của AA (chỉ dùng khi tắt thiết lập 'gửi cho tư vấn viên trên planner AA là bản demo') yêu cầu tên và số điện thoại hoặc e-mail của khách trước khi gửi. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị cấu hình riêng trên máy chủ, rồi tới giá trị mặc định này.", "raise": "Bật: mọi lần chuyển khách đều có thông tin liên hệ để đội ngũ liên lạc lại.", "lower": "Tắt: khách gửi được mà không cần thông tin; nhiều lượt chuyển hơn, nhiều lượt không có cách liên lạc.", "when": "Chỉ có tác dụng khi tắt công tắc demo; chỉ tắt để thử luồng.", "example": "Với mặc định on: khách phải nhập tên và số điện thoại hoặc e-mail trước."}}},
{"key": "tripplanner.leads.hold_days", "label": "Undelivered lead: days kept before redaction", "guide": {"en": {"what": "How many days TripPlanner keeps a lead it could not deliver to the agency before it removes the traveller's details anyway. Data rules allow at most 7 days; the minimum of 3 keeps two daily clean-up runs of margin. If TripPlanner cannot read the settings, it falls back to its own server value, then this default.", "raise": "Delivery has longer to recover from an outage before the lead is lost; personal data is kept longer (never over 7 days).", "lower": "Personal data is removed sooner; a longer outage loses more leads.", "when": "Lower it if the privacy review asks for shorter keeping; keep it high while lead delivery is unstable.", "example": "With the default of 7 days: an undelivered lead loses its contact details on day 7."}, "vi": {"what": "TripPlanner giữ lead chưa giao được cho đại lý bao nhiêu ngày trước khi vẫn xoá thông tin cá nhân của khách. Quy định dữ liệu cho phép tối đa 7 ngày; mức tối thiểu 3 chừa khoảng cho hai lần dọn dẹp hằng ngày. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị cấu hình riêng trên máy chủ, rồi tới giá trị mặc định này.", "raise": "Việc giao lead có thêm thời gian phục hồi sau sự cố trước khi mất lead; dữ liệu cá nhân được giữ lâu hơn (không quá 7 ngày).", "lower": "Dữ liệu cá nhân được xoá sớm hơn; sự cố kéo dài làm mất nhiều lead hơn.", "when": "Giảm nếu đánh giá quyền riêng tư yêu cầu giữ ngắn hơn; để cao khi việc giao lead chưa ổn định.", "example": "Với mặc định 7 ngày: lead chưa giao bị xoá thông tin liên hệ vào ngày thứ 7."}}},
{"key": "tripplanner.leads.tenant_daily_cap", "label": "Leads per agency per 24 hours", "guide": {"en": {"what": "How many leads one agency may receive in 24 hours. Past it a 'send to advisor' is refused before anything is stored, so a script on a public planner cannot flood the agency's inbox or CRM. A value set for one agency overrides this platform value. If TripPlanner cannot read the settings, it falls back to its own server value, then this default.", "raise": "A busy agency is not cut off; a flood of fake leads can grow larger before it stops.", "lower": "Floods stop sooner; a very busy agency may lose real leads at the end of a day.", "when": "Raise it for an agency that really gets this many enquiries (per agency); lower it after a lead flood.", "example": "With the default of 200: the 201st lead of an agency within 24 hours is refused."}, "vi": {"what": "Một đại lý được nhận tối đa bao nhiêu lead trong 24 giờ. Vượt mức thì yêu cầu 'gửi cho tư vấn viên' bị từ chối trước khi lưu gì, để một script trên planner công khai không làm ngập hộp thư hay CRM của đại lý. Giá trị đặt riêng cho một đại lý sẽ thay giá trị chung này. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị cấu hình riêng trên máy chủ, rồi tới giá trị mặc định này.", "raise": "Đại lý đông khách không bị cắt; đợt lead giả có thể lớn hơn trước khi bị chặn.", "lower": "Đợt lead giả bị chặn sớm hơn; đại lý rất đông khách có thể mất lead thật cuối ngày.", "when": "Tăng cho đại lý thật sự nhận nhiều yêu cầu như vậy (đặt riêng); giảm sau một đợt lead giả.", "example": "Với mặc định 200: lead thứ 201 của một đại lý trong 24 giờ bị từ chối."}}},
{"key": "tripplanner.rate.chat_ip_per_hour", "label": "Planning chat messages per visitor IP per hour", "guide": {"en": {"what": "How many planning chat messages one traveller IP address may send in an hour, counting only messages that reach a model. It catches one machine opening many sessions. Past it the planner answers 'too many requests' and asks them to wait. If TripPlanner cannot read the settings, it falls back to its own server value, then this default.", "raise": "Heavy users are stopped less often; a script can run up more paid calls before it is stopped.", "lower": "Paid calls are better protected from abuse; a busy real traveller may hit the limit.", "when": "Raise it when real travellers report 'too many requests'; lower it when the AI call log shows one visitor running up cost.", "example": "With the default of 40: the 41st message in an hour is refused."}, "vi": {"what": "Số tin nhắn trò chuyện lập kế hoạch một địa chỉ IP của khách được gửi mỗi giờ, chỉ tính tin có tới model. Nó chặn trường hợp một máy mở nhiều phiên. Vượt mức thì planner báo 'quá nhiều yêu cầu' và đề nghị chờ. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị cấu hình riêng trên máy chủ, rồi tới giá trị mặc định này.", "raise": "Người dùng nhiều ít bị chặn hơn; một script có thể gây thêm nhiều lượt gọi có phí trước khi bị chặn.", "lower": "Lượt gọi có phí được bảo vệ tốt hơn khỏi lạm dụng; khách thật dùng nhiều có thể chạm giới hạn.", "when": "Tăng khi khách thật báo 'quá nhiều yêu cầu'; giảm khi nhật ký gọi AI cho thấy một khách gây tốn kém.", "example": "Với mặc định 40: tin nhắn thứ 41 trong cùng một giờ bị từ chối."}}},
{"key": "tripplanner.rate.chat_per_hour", "label": "Planning chat messages per visitor session per hour", "guide": {"en": {"what": "How many planning chat messages one guest session may send in an hour, counting only messages that reach a model. A signed-in traveller gets the signed-in factor times this. Past it the planner answers 'too many requests' and asks them to wait. If TripPlanner cannot read the settings, it falls back to its own server value, then this default.", "raise": "Heavy users are stopped less often; a script can run up more paid calls before it is stopped.", "lower": "Paid calls are better protected from abuse; a busy real traveller may hit the limit.", "when": "Raise it when real travellers report 'too many requests'; lower it when the AI call log shows one visitor running up cost.", "example": "With the default of 20: the 21st message in an hour is refused."}, "vi": {"what": "Số tin nhắn trò chuyện lập kế hoạch một phiên khách được gửi mỗi giờ, chỉ tính tin có tới model. Khách đã đăng nhập được nhân thêm theo hệ số đăng nhập. Vượt mức thì planner báo 'quá nhiều yêu cầu' và đề nghị chờ. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị cấu hình riêng trên máy chủ, rồi tới giá trị mặc định này.", "raise": "Người dùng nhiều ít bị chặn hơn; một script có thể gây thêm nhiều lượt gọi có phí trước khi bị chặn.", "lower": "Lượt gọi có phí được bảo vệ tốt hơn khỏi lạm dụng; khách thật dùng nhiều có thể chạm giới hạn.", "when": "Tăng khi khách thật báo 'quá nhiều yêu cầu'; giảm khi nhật ký gọi AI cho thấy một khách gây tốn kém.", "example": "Với mặc định 20: tin nhắn thứ 21 trong cùng một giờ bị từ chối."}}},
{"key": "tripplanner.rate.narrate_per_hour", "label": "AI trip stories per visitor session per hour", "guide": {"en": {"what": "How many AI trip stories (the narration of a planned trip) one guest session may ask for in an hour, counting only requests that call a model (a cached story is free and not counted). A signed-in traveller gets the signed-in factor times this. Past it the planner answers 'too many requests' and asks them to wait. If TripPlanner cannot read the settings, it falls back to its own server value, then this default.", "raise": "Heavy users are stopped less often; a script can run up more paid calls before it is stopped.", "lower": "Paid calls are better protected from abuse; a busy real traveller may hit the limit.", "when": "Raise it when real travellers report 'too many requests'; lower it when the AI call log shows one visitor running up cost.", "example": "With the default of 10: the 11th story in an hour is refused."}, "vi": {"what": "Số câu chuyện chuyến đi bằng AI (lời kể cho lịch trình đã lập) một phiên khách được yêu cầu mỗi giờ, chỉ tính các yêu cầu có gọi model (câu chuyện đã lưu sẵn thì miễn phí, không tính). Khách đã đăng nhập được nhân thêm theo hệ số đăng nhập. Vượt mức thì planner báo 'quá nhiều yêu cầu' và đề nghị chờ. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị cấu hình riêng trên máy chủ, rồi tới giá trị mặc định này.", "raise": "Người dùng nhiều ít bị chặn hơn; một script có thể gây thêm nhiều lượt gọi có phí trước khi bị chặn.", "lower": "Lượt gọi có phí được bảo vệ tốt hơn khỏi lạm dụng; khách thật dùng nhiều có thể chạm giới hạn.", "when": "Tăng khi khách thật báo 'quá nhiều yêu cầu'; giảm khi nhật ký gọi AI cho thấy một khách gây tốn kém.", "example": "Với mặc định 10: câu chuyện thứ 11 trong cùng một giờ bị từ chối."}}},
{"key": "tripplanner.rate.search_per_minute", "label": "AI searches per visitor IP per minute", "guide": {"en": {"what": "How many free-text searches one traveller IP address may run in a minute, counting only searches that call the AI search model (an empty search is not counted). A signed-in traveller gets the signed-in factor times this. Past it the planner answers 'too many requests' and asks them to wait. If TripPlanner cannot read the settings, it falls back to its own server value, then this default.", "raise": "Heavy users are stopped less often; a script can run up more paid calls before it is stopped.", "lower": "Paid calls are better protected from abuse; a busy real traveller may hit the limit.", "when": "Raise it when real travellers report 'too many requests'; lower it when the AI call log shows one visitor running up cost.", "example": "With the default of 30: the 31st search in a minute is refused."}, "vi": {"what": "Số lượt tìm kiếm tự do một địa chỉ IP của khách được chạy mỗi phút, chỉ tính các lượt có gọi model tìm kiếm AI (ô tìm kiếm trống không tính). Khách đã đăng nhập được nhân thêm theo hệ số đăng nhập. Vượt mức thì planner báo 'quá nhiều yêu cầu' và đề nghị chờ. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị cấu hình riêng trên máy chủ, rồi tới giá trị mặc định này.", "raise": "Người dùng nhiều ít bị chặn hơn; một script có thể gây thêm nhiều lượt gọi có phí trước khi bị chặn.", "lower": "Lượt gọi có phí được bảo vệ tốt hơn khỏi lạm dụng; khách thật dùng nhiều có thể chạm giới hạn.", "when": "Tăng khi khách thật báo 'quá nhiều yêu cầu'; giảm khi nhật ký gọi AI cho thấy một khách gây tốn kém.", "example": "Với mặc định 30: lượt tìm thứ 31 trong cùng một phút bị từ chối."}}},
{"key": "tripplanner.rate.send_ip_per_hour", "label": "Leads per visitor IP per hour", "guide": {"en": {"what": "How many 'send to advisor' requests one traveller IP address may make in an hour on an agency's planner, counting only requests that store a lead. It catches one machine opening many sessions. Past it the planner answers 'too many requests' and asks them to wait. If TripPlanner cannot read the settings, it falls back to its own server value, then this default.", "raise": "Several travellers on one network (a hotel, an office) can send more leads; a script on one machine can push more fake leads with contact details into the agency's inbox and CRM before it is stopped.", "lower": "Fake-lead floods from one machine stop sooner; travellers who share a network may be refused.", "when": "Lower it when agencies report spam leads; raise it when real travellers report 'too many requests' when they send to an advisor.", "example": "With the default of 20: the 21st lead in an hour is refused."}, "vi": {"what": "Số yêu cầu 'gửi cho tư vấn viên' một địa chỉ IP của khách được gửi mỗi giờ trên planner của đại lý, chỉ tính các yêu cầu có lưu lead. Nó chặn trường hợp một máy mở nhiều phiên. Vượt mức thì planner báo 'quá nhiều yêu cầu' và đề nghị chờ. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị cấu hình riêng trên máy chủ, rồi tới giá trị mặc định này.", "raise": "Nhiều khách dùng chung một mạng (khách sạn, văn phòng) gửi được nhiều lead hơn; một script trên một máy có thể đẩy thêm nhiều lead giả kèm thông tin liên hệ vào hộp thư và CRM của đại lý trước khi bị chặn.", "lower": "Đợt lead giả từ một máy bị chặn sớm hơn; khách dùng chung một mạng có thể bị từ chối.", "when": "Giảm khi đại lý báo nhận lead rác; tăng khi khách thật báo 'quá nhiều yêu cầu' lúc gửi cho tư vấn viên.", "example": "Với mặc định 20: lead thứ 21 trong cùng một giờ bị từ chối."}}},
{"key": "tripplanner.rate.send_per_hour", "label": "Leads per visitor session per hour", "guide": {"en": {"what": "How many 'send to advisor' requests (a lead with the traveller's contact) one guest session may make in an hour on an agency's planner, counting only requests that store a lead. A signed-in traveller gets the signed-in factor times this. Past it the planner answers 'too many requests' and asks them to wait. If TripPlanner cannot read the settings, it falls back to its own server value, then this default.", "raise": "A real traveller can resend more often; a script can push more fake leads with contact details into the agency's inbox and CRM before it is stopped.", "lower": "Fake-lead floods stop sooner; a traveller who retries several times may be refused.", "when": "Lower it when agencies report spam leads; raise it when real travellers report 'too many requests' when they send to an advisor.", "example": "With the default of 5: the 6th lead in an hour is refused."}, "vi": {"what": "Số yêu cầu 'gửi cho tư vấn viên' (một lead kèm thông tin liên hệ của khách) một phiên khách được gửi mỗi giờ trên planner của đại lý, chỉ tính các yêu cầu có lưu lead. Khách đã đăng nhập được nhân thêm theo hệ số đăng nhập. Vượt mức thì planner báo 'quá nhiều yêu cầu' và đề nghị chờ. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị cấu hình riêng trên máy chủ, rồi tới giá trị mặc định này.", "raise": "Khách thật được gửi lại nhiều lần hơn; một script có thể đẩy thêm nhiều lead giả kèm thông tin liên hệ vào hộp thư và CRM của đại lý trước khi bị chặn.", "lower": "Đợt lead giả bị chặn sớm hơn; khách gửi lại vài lần có thể bị từ chối.", "when": "Giảm khi đại lý báo nhận lead rác; tăng khi khách thật báo 'quá nhiều yêu cầu' lúc gửi cho tư vấn viên.", "example": "Với mặc định 5: lead thứ 6 trong cùng một giờ bị từ chối."}}},
{"key": "tripplanner.rate.signed_in_factor", "label": "Signed-in traveller allowance factor", "guide": {"en": {"what": "A signed-in traveller gets this many times every per-session and per-IP allowance (trip stories, search, send to advisor, planning chat). 1 = no extra allowance. If TripPlanner cannot read the settings, it falls back to its own server value, then this default.", "raise": "Signed-in travellers can use the planner more before they hit a limit; an abused account can cost more.", "lower": "Signed-in travellers are limited like guests.", "when": "Raise it when signed-in travellers report 'too many requests'; lower it if accounts are created to get around the limits.", "example": "With the default of 2: a signed-in traveller may ask for 20 AI trip stories an hour where a guest gets 10."}, "vi": {"what": "Khách đã đăng nhập được gấp bao nhiêu lần mọi hạn mức theo phiên và theo IP (câu chuyện chuyến đi, tìm kiếm, gửi cho tư vấn viên, trò chuyện lập kế hoạch). 1 = không thêm. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị cấu hình riêng trên máy chủ, rồi tới giá trị mặc định này.", "raise": "Khách đăng nhập dùng planner được nhiều hơn trước khi chạm giới hạn; tài khoản bị lạm dụng có thể gây tốn hơn.", "lower": "Khách đăng nhập bị giới hạn như khách vãng lai.", "when": "Tăng khi khách đăng nhập báo 'quá nhiều yêu cầu'; giảm nếu có người tạo tài khoản để lách giới hạn.", "example": "Với mặc định 2: khách đăng nhập được 20 câu chuyện chuyến đi mỗi giờ, khách vãng lai được 10."}}},
{"key": "tripplanner.spend.plan_chat_monthly_cap_usd", "label": "Planning chat: monthly spend cap (whole app)", "guide": {"en": {"what": "The most the planning chat of the whole TripPlanner app may spend on AI calls in one calendar month (UTC). At the cap the chat pauses with a plain message; the rest of the planner keeps working. The app's daily cap (AI gateway > App profiles) and each agency's AI budget apply too. If TripPlanner cannot read the settings, it falls back to its own server value, then this default.", "raise": "The chat stays open longer in a busy month; the month can cost more.", "lower": "The chat pauses sooner in a busy month.", "when": "Raise it when the chat pauses before month end and its use is real; lower it when spend grows without bookings or leads to show for it.", "example": "With the default of 2 USD a month: the chat pauses for the rest of the month once 2 USD is spent."}, "vi": {"what": "Số tiền tối đa phần trò chuyện lập kế hoạch của cả ứng dụng TripPlanner được chi cho lượt gọi AI trong một tháng (theo UTC). Chạm mức thì trò chuyện tạm dừng với một thông báo đơn giản; phần còn lại của planner vẫn chạy. Mức trần theo ngày của ứng dụng (AI gateway > App profiles) và ngân sách AI của từng đại lý cũng áp dụng. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị cấu hình riêng trên máy chủ, rồi tới giá trị mặc định này.", "raise": "Trò chuyện mở lâu hơn trong tháng đông khách; tháng đó có thể tốn hơn.", "lower": "Trò chuyện tạm dừng sớm hơn trong tháng đông khách.", "when": "Tăng khi trò chuyện dừng trước cuối tháng mà nhu cầu là thật; giảm khi chi phí tăng mà không có booking hay lead tương ứng.", "example": "Với mặc định 2 USD mỗi tháng: chi đủ 2 USD thì trò chuyện dừng tới hết tháng."}}},
{"key": "tripplanner.spend.plan_chat_tenant_monthly_cap_usd", "label": "Planning chat: monthly spend cap per agency", "guide": {"en": {"what": "The most the planning chat may spend on AI calls for one agency in one calendar month (UTC), the AA demo included. A value set for one agency overrides this platform value for that agency. If TripPlanner cannot read the settings, it falls back to its own server value, then this default.", "raise": "Each agency's travellers can chat more in a month; one busy agency can cost more.", "lower": "Each agency's chat pauses sooner; the cost of one agency is better bounded.", "when": "Raise it for agencies whose travellers really use the chat (per agency, on the tenant row); lower it if one agency's chat costs more than it brings.", "example": "With the default of 2 USD a month: an agency's chat pauses for the month after 2 USD of its own spend."}, "vi": {"what": "Số tiền tối đa phần trò chuyện lập kế hoạch được chi cho lượt gọi AI của một đại lý trong một tháng (theo UTC), kể cả bản demo của AA. Giá trị đặt riêng cho một đại lý sẽ thay giá trị chung này cho đại lý đó. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị cấu hình riêng trên máy chủ, rồi tới giá trị mặc định này.", "raise": "Khách của mỗi đại lý trò chuyện được nhiều hơn mỗi tháng; một đại lý đông khách có thể tốn hơn.", "lower": "Trò chuyện của mỗi đại lý dừng sớm hơn; chi phí của một đại lý được giới hạn chặt hơn.", "when": "Tăng cho đại lý có khách thật sự dùng trò chuyện (đặt riêng trên dòng của đại lý); giảm nếu trò chuyện của một đại lý tốn hơn giá trị mang lại.", "example": "Với mặc định 2 USD mỗi tháng: trò chuyện của đại lý dừng tới hết tháng khi đại lý đó đã chi 2 USD."}}}]$guide$::jsonb) AS g (key text, label text, guide jsonb)
ON CONFLICT (key) DO UPDATE SET label = EXCLUDED.label, guide = EXCLUDED.guide;
-- settings-guide:end

UPDATE shared.setting_definition AS d
   SET label = g.label, guide = g.guide
  FROM m416_guide AS g
 WHERE d.key = g.key
   AND (d.label IS DISTINCT FROM g.label OR d.guide IS DISTINCT FROM g.guide);

-- Post-check: every key of the block exists with its complete guide (a misspelt key would leave a setting unexplained
-- without an error), and no definition is left without a guide.
DO $check$
DECLARE
    missing text;
    unguided text;
BEGIN
    SELECT string_agg(g.key, ', ' ORDER BY g.key) INTO missing
      FROM m416_guide AS g
     WHERE NOT EXISTS (SELECT 1 FROM shared.setting_definition AS d
                        WHERE d.key = g.key AND d.guide = g.guide AND shared.setting_guide_complete(d.guide));
    IF missing IS NOT NULL THEN
        RAISE EXCEPTION 'CIS 416: no definition or no complete guide for %', missing;
    END IF;
    SELECT string_agg(d.key, ', ' ORDER BY d.key) INTO unguided
      FROM shared.setting_definition AS d
     WHERE d.guide IS NULL;
    IF unguided IS NOT NULL THEN
        RAISE EXCEPTION 'CIS 416: definitions without a guide: %', unguided;
    END IF;
END
$check$;

INSERT INTO shared.schema_versions (version, applied_at, description)
VALUES ('416', now(), 'AA-1096 l23: operator guides (EN + VI) and plain labels of the platform settings')
ON CONFLICT (version) DO NOTHING;

COMMIT;
